// Plus Two entrance chemistry bank: Chemical thermodynamics. Original fibub questions.
// Data used: R = 8.314 J/(mol K); 1 L atm = 101.3 J; c(water) = 4.18 J/(g K); neutralisation of strong acid and base = -57.1 kJ/mol.
// dHf (kJ/mol): CO2 -393.5, H2O(l) -285.8, CH4 -74.8, C2H6 -84.7, C2H4 +52.3, C3H8 -103.8. gamma: monatomic 5/3, diatomic 7/5.
import { pick, int, choose, fmt, shuffleOpts, numOpts } from '../_entrance.js';

let _n = 0;
const EX = { 1: ['keam', 'cusat', 'comedk', 'jee-main', 'neet'], 2: ['keam', 'cusat', 'comedk', 'jee-main', 'neet'], 3: ['jee-main', 'neet', 'comedk'], 4: ['jee-main', 'jee-adv', 'neet'], 5: ['jee-adv'] };
const A4 = ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'];
const S4 = ['Both Statement I and Statement II are correct', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct', 'Both Statement I and Statement II are incorrect'];
const mk = (id, level, sub, q, right, wrongs, sol, trap) => {
  const pos = (_n++) % 4; const options = [...wrongs]; options.splice(pos, 0, right);
  return { id, type: 'mcq', level, format: 'single', exams: EX[level], sub, q, options, answer: pos, sol, ...(trap ? { trap } : {}) };
};
const nat = (id, level, sub, q, answer, tol, unit, sol, trap) => ({ id, type: 'nat', level, format: tol === 0 ? 'integer' : 'numeric', exams: EX[level], sub, q, answer, tol, ...(unit ? { unit } : {}), sol, ...(trap ? { trap } : {}) });
const msq = (id, level, sub, q, options, answer, sol, trap) => ({ id, type: 'msq', level, format: 'multi', exams: level >= 4 ? ['jee-adv'] : ['jee-adv', 'jee-main'], sub, q, options, answer, sol, ...(trap ? { trap } : {}) });
const asr = (id, level, sub, A, R, answer, sol, trap) => ({ id, type: 'mcq', level, format: 'assertion', exams: EX[level], sub, q: `<p><b>Assertion (A):</b> ${A}</p><p><b>Reason (R):</b> ${R}</p>`, options: A4, answer, sol, ...(trap ? { trap } : {}) });
const stm = (id, level, sub, s1, s2, answer, sol, trap) => ({ id, type: 'mcq', level, format: 'statements', exams: EX[level], sub, q: `<p><b>Statement I:</b> ${s1}</p><p><b>Statement II:</b> ${s2}</p>`, options: S4, answer, sol, ...(trap ? { trap } : {}) });
const mat = (id, level, sub, group, q, right, wrongs, sol, trap) => ({ ...mk(id, level, sub, q, right, wrongs, sol, trap), format: 'match', group });
const P = (id, level, sub, group, q, right, wrongs, sol, trap) => ({ ...mk(id, level, sub, q, right, wrongs, sol, trap), format: 'passage', group });
const PN = (id, level, sub, group, q, answer, tol, unit, sol, trap) => ({ ...nat(id, level, sub, q, answer, tol, unit, sol, trap), format: 'passage', group });

const R = 8.314;
// reactions with the change in moles of gas
const RX = [
  ['N<sub>2</sub>(g) + 3H<sub>2</sub>(g) &rarr; 2NH<sub>3</sub>(g)', -2], ['2SO<sub>2</sub>(g) + O<sub>2</sub>(g) &rarr; 2SO<sub>3</sub>(g)', -1],
  ['PCl<sub>5</sub>(g) &rarr; PCl<sub>3</sub>(g) + Cl<sub>2</sub>(g)', 1], ['2H<sub>2</sub>(g) + O<sub>2</sub>(g) &rarr; 2H<sub>2</sub>O(l)', -3],
  ['C(graphite) + O<sub>2</sub>(g) &rarr; CO<sub>2</sub>(g)', 0], ['CaCO<sub>3</sub>(s) &rarr; CaO(s) + CO<sub>2</sub>(g)', 1],
  ['C<sub>2</sub>H<sub>4</sub>(g) + 3O<sub>2</sub>(g) &rarr; 2CO<sub>2</sub>(g) + 2H<sub>2</sub>O(l)', -2], ['2NO<sub>2</sub>(g) &rarr; N<sub>2</sub>O<sub>4</sub>(g)', -1],
];
// fuels: name, carbon atoms, hydrogen atoms, dHf (kJ/mol)
const FUELS = [['CH<sub>4</sub>', 1, 4, -74.8], ['C<sub>2</sub>H<sub>6</sub>', 2, 6, -84.7], ['C<sub>2</sub>H<sub>4</sub>', 2, 4, 52.3], ['C<sub>3</sub>H<sub>8</sub>', 3, 8, -103.8]];
// bond enthalpies for H2 + X2 -> 2HX: HH, XX, HX
const HX = [['Cl', 242, 431], ['Br', 193, 366], ['I', 151, 299], ['F', 159, 565]];
const SUBS = [['water', 40.7, 373], ['benzene', 30.8, 353], ['ethanol', 38.6, 351], ['ammonia', 23.4, 240], ['mercury', 59.1, 630]];
const sg = (x) => (x > 0 ? '+' : '') + x;

// shared match helper (pasted into each ext)
const XGR = {};
const M = (id, level, sub, title, l1, l2, map, sol, trap) => {
  const L = 'ABCD', Q = 'pqrst';
  XGR[id] = { title, list1: l1.map((t, i) => `${L[i]}. ${t}`), list2: l2.map((t, i) => `${Q[i]}. ${t}`) };
  const code = (m) => m.map((x, i) => `${L[i]}-${x}`).join(', ');
  const sw = (a, i, j) => { const b = [...a]; [b[i], b[j]] = [b[j], b[i]]; return b; };
  const wr = [sw(map, 0, 1), sw(map, 1, 2), sw(map, 2, 3), sw(map, 0, 3), sw(map, 0, 2)].map(code).filter((c) => c !== code(map));
  return mat(id, level, sub, id, 'Match the entries of List I with those of List II and choose the correct code.', code(map), wr.slice(0, 3), sol, trap);
};
// ---- expansion set (ct-x01 onward) ----
const XI = [
  mk('ct-x01', 2, 'properties', 'Which of the following is an <b>extensive</b> property?', 'Heat capacity of a sample', ['Density', 'Molar enthalpy', 'Specific heat capacity'], '<p>An extensive property depends on how much matter there is. Heat capacity (J K<sup>-1</sup>) doubles when the sample doubles. Density, molar enthalpy and specific heat capacity are per unit mass or per mole, so they are intensive.</p>', 'Adding "per mole" or "specific" turns an extensive property into an intensive one.'),
  nat('ct-x02', 2, 'work of expansion', 'A gas expands from 3.0 L to 8.0 L against a constant external pressure of 2.0 atm. The magnitude of the work done by the gas, in L atm, is', 10, 0, 'L atm', '<p>Work = p<sub>ext</sub>&Delta;V = 2.0 &times; (8.0 - 3.0) = <b>10 L atm</b>.</p>'),
  mk('ct-x03', 2, 'first law', 'A system absorbs 300 J of heat and does 120 J of work on the surroundings. Its change in internal energy is', '+180 J', ['+420 J', '-180 J', '-420 J'], '<p>&Delta;U = q + w with the IUPAC sign convention. q = +300 J. Work done <i>by</i> the system is negative for w: w = -120 J.</p><p>&Delta;U = 300 - 120 = <b>+180 J</b>.</p>', 'Work done by the system carries a minus sign in &Delta;U = q + w.'),
  mk('ct-x04', 2, 'enthalpy of formation', 'Which substance has &Delta;<sub>f</sub>H&deg; = 0 at 298 K and 1 bar?', 'Hg(l)', ['Br<sub>2</sub>(g)', 'I<sub>2</sub>(g)', 'C(diamond)'], '<p>&Delta;<sub>f</sub>H&deg; is zero for an element in its most stable form at the stated T and p. Mercury is a liquid at 298 K, so Hg(l) is the reference form. Bromine is a liquid (not gas), iodine is a solid (not gas) and graphite, not diamond, is the stable form of carbon.</p>'),
  mk('ct-x05', 2, 'entropy', 'At a given temperature, which has the highest molar entropy?', 'H<sub>2</sub>O(g)', ['H<sub>2</sub>O(l)', 'H<sub>2</sub>O(s)', 'All have the same entropy'], '<p>Gases have far more freedom of motion than liquids, and liquids more than solids, so S(g) &gt; S(l) &gt; S(s). Water vapour has the highest molar entropy.</p>'),
  nat('ct-x06', 2, 'state functions', 'How many of these are state functions: q, w, U, H, S, G, V?', 5, 0, '', '<p>Heat q and work w depend on the path. U, H, S, G and V depend only on the state. So there are <b>5</b>.</p>'),

  mk('ct-x07', 3, 'Hess law', 'Given: S(s) + O<sub>2</sub>(g) &rarr; SO<sub>2</sub>(g), &Delta;H = -297 kJ; SO<sub>2</sub>(g) + &frac12;O<sub>2</sub>(g) &rarr; SO<sub>3</sub>(g), &Delta;H = -99 kJ. &Delta;<sub>f</sub>H of SO<sub>3</sub>(g) in kJ mol<sup>-1</sup> is', '-396', ['-198', '+396', '-297'], '<p>S + 3/2 O<sub>2</sub> &rarr; SO<sub>3</sub> is the sum of the two steps, so &Delta;H = -297 + (-99) = <b>-396 kJ mol<sup>-1</sup></b>.</p>', 'The two enthalpies add; do not subtract them.'),
  nat('ct-x08', 3, 'calorimetry', '50 g of a metal at 100 &deg;C is dropped into 100 g of water at 20 &deg;C. The final temperature is 25 &deg;C. Heat lost to the cup is negligible. The specific heat of the metal, in J g<sup>-1</sup> K<sup>-1</sup>, is (c of water = 4.18)', 0.557, 0.005, 'J g<sup>-1</sup> K<sup>-1</sup>', '<p>Heat lost by metal = heat gained by water.</p><p>50 &times; c &times; (100 - 25) = 100 &times; 4.18 &times; (25 - 20)</p><p>3750 c = 2090, so c = <b>0.557 J g<sup>-1</sup> K<sup>-1</sup></b>.</p>'),
  nat('ct-x09', 3, '&Delta;H and &Delta;U', '<p>For how many of these reactions is &Delta;H equal to &Delta;U?</p><p>(i) H<sub>2</sub>(g) + I<sub>2</sub>(g) &rarr; 2HI(g)<br>(ii) N<sub>2</sub>(g) + O<sub>2</sub>(g) &rarr; 2NO(g)<br>(iii) CaCO<sub>3</sub>(s) &rarr; CaO(s) + CO<sub>2</sub>(g)<br>(iv) C(s) + O<sub>2</sub>(g) &rarr; CO<sub>2</sub>(g)<br>(v) 2SO<sub>2</sub>(g) + O<sub>2</sub>(g) &rarr; 2SO<sub>3</sub>(g)</p>', 3, 0, '', '<p>&Delta;H = &Delta;U + &Delta;n<sub>g</sub>RT, so they are equal when &Delta;n<sub>g</sub> = 0.</p><p>(i) 2 - 2 = 0; (ii) 2 - 2 = 0; (iii) +1; (iv) 1 - 1 = 0; (v) 2 - 3 = -1. Equal in (i), (ii), (iv): <b>3</b>.</p>', 'Solids do not count in &Delta;n<sub>g</sub>.'),
  nat('ct-x10', 3, 'entropy of heating', '2.0 mol of an ideal gas with C<sub>p,m</sub> = 29.1 J K<sup>-1</sup> mol<sup>-1</sup> is heated at constant pressure from 300 K to 600 K. &Delta;S in J K<sup>-1</sup> is', +(2 * 29.1 * Math.log(2)).toFixed(2), 0.1, 'J K<sup>-1</sup>', `<p>&Delta;S = nC<sub>p,m</sub> ln(T<sub>2</sub>/T<sub>1</sub>) = 2.0 &times; 29.1 &times; ln 2 = 58.2 &times; 0.6931 = <b>${(2 * 29.1 * Math.log(2)).toFixed(2)} J K<sup>-1</sup></b>.</p>`),
  mk('ct-x11', 3, 'free expansion', 'An ideal gas expands into an evacuated container (free expansion) inside an insulated box. Which set is correct?', 'q = 0, w = 0, &Delta;U = 0, &Delta;S(system) &gt; 0', ['q = 0, w = 0, &Delta;U = 0, &Delta;S(system) = 0', 'q &gt; 0, w &lt; 0, &Delta;U = 0, &Delta;S(system) &gt; 0', 'q = 0, w &lt; 0, &Delta;U &lt; 0, &Delta;S(system) = 0'], '<p>No external pressure means no work (w = 0). The box is insulated, so q = 0, hence &Delta;U = 0. An ideal gas has no change in T, so it behaves like an isothermal expansion: S depends on volume and rises by nR ln(V<sub>2</sub>/V<sub>1</sub>).</p>', 'Entropy is a state function: use a reversible path to find it, even if the real path is free expansion.'),
  nat('ct-x12', 3, '&Delta;G and K', 'For a reaction at 298 K, &Delta;G&deg; = -17.1 kJ mol<sup>-1</sup>. log<sub>10</sub>K to the nearest whole number is (R = 8.314 J K<sup>-1</sup> mol<sup>-1</sup>)', 3, 0, '', `<p>&Delta;G&deg; = -2.303 RT log K, so log K = 17100 / (2.303 &times; 8.314 &times; 298) = 17100 / 5706 = ${(17100 / (Math.log(10) * R * 298)).toFixed(2)}, which is <b>3</b>.</p>`, 'Convert kJ to J before using R.'),
  nat('ct-x13', 3, 'Trouton rule', 'A liquid has &Delta;<sub>vap</sub>H = 29.3 kJ mol<sup>-1</sup>. Using Trouton&rsquo;s rule (&Delta;<sub>vap</sub>S &asymp; 88 J K<sup>-1</sup> mol<sup>-1</sup>), its normal boiling point in K is about', 333, 3, 'K', '<p>At the boiling point &Delta;G = 0, so T<sub>b</sub> = &Delta;H/&Delta;S = 29300 / 88 = <b>333 K</b>.</p>'),
  mk('ct-x14', 3, 'spontaneity', 'A reaction mixture is at equilibrium at constant T and p. Which statement is correct?', '&Delta;G = 0 for the mixture, while &Delta;G&deg; = -RT ln K need not be zero', ['&Delta;G&deg; is always zero at equilibrium', '&Delta;G = &Delta;G&deg; because Q = 1 at equilibrium', '&Delta;G is negative because the forward and backward rates are equal'], '<p>&Delta;G = &Delta;G&deg; + RT ln Q. At equilibrium Q = K, so &Delta;G = &Delta;G&deg; + RT ln K = 0. &Delta;G&deg; itself equals -RT ln K, which is zero only when K = 1. Q equals K (not 1) at equilibrium, and equal rates give &Delta;G = 0, not a negative value.</p>'),
  mk('ct-x15', 3, 'heat capacity', 'For 3.0 mol of an ideal gas, C<sub>p</sub> - C<sub>v</sub> (in J K<sup>-1</sup>) is', '24.9', ['8.31', '74.8', '12.5'], `<p>For one mole, C<sub>p,m</sub> - C<sub>v,m</sub> = R. For 3 mol: 3 &times; 8.314 = <b>${(3 * R).toFixed(1)} J K<sup>-1</sup></b>.</p>`, 'The relation is per mole; multiply by n for the sample.'),
  asr('ct-x16', 3, 'enthalpy', 'The absolute value of the enthalpy of a substance cannot be measured.', 'Only changes in enthalpy can be measured, because H = U + pV and the internal energy U has no absolute zero.', 0, '<p>Both are true and R is the reason. We can only measure the heat exchanged when a system goes from one state to another, i.e. a difference in H. That is why we choose a reference (elements in their standard states) and tabulate &Delta;<sub>f</sub>H&deg;.</p>'),
  stm('ct-x17', 3, '&Delta;H and &Delta;U', 'For H<sub>2</sub>(g) + I<sub>2</sub>(g) &rarr; 2HI(g), &Delta;H = &Delta;U.', 'For N<sub>2</sub>(g) + 3H<sub>2</sub>(g) &rarr; 2NH<sub>3</sub>(g), &Delta;H = &Delta;U.', 1, '<p>&Delta;H - &Delta;U = &Delta;n<sub>g</sub>RT. For the HI reaction &Delta;n<sub>g</sub> = 2 - 2 = 0, so Statement I is correct. For ammonia &Delta;n<sub>g</sub> = 2 - 4 = -2, so &Delta;H &ne; &Delta;U and Statement II is incorrect.</p>'),
  M('ct-x18', 3, 'ideal gas processes', 'Match the ideal-gas process with its feature', ['Reversible isothermal expansion', 'Free expansion into vacuum', 'Reversible adiabatic compression', 'Melting of ice at 273 K and 1 atm'], ['q = 0 and &Delta;S(system) = 0', '&Delta;G = 0', 'w = 0 and &Delta;S(system) &gt; 0', 'q = -w, not zero'], ['s', 'r', 'p', 'q'], '<p>A: &Delta;U = 0 so q = -w, and neither is zero: s. B: no work, and entropy rises as volume increases: r. C: no heat exchange and reversible, so dS = q<sub>rev</sub>/T = 0: p. D: a phase change at its equilibrium temperature has &Delta;G = 0: q.</p>'),
  M('ct-x19', 3, 'laws and relations', 'Match the law or rule with what it says', ['Hess&rsquo;s law', 'Kirchhoff&rsquo;s equation', 'Link between &Delta;G&deg; and the equilibrium constant', 'Trouton&rsquo;s rule'], ['&Delta;<sub>r</sub>H<sub>2</sub> - &Delta;<sub>r</sub>H<sub>1</sub> = &Delta;C<sub>p</sub>(T<sub>2</sub> - T<sub>1</sub>)', '&Delta;G&deg; = -RT ln K', 'The enthalpy change is the same whether the reaction is done in one step or several', '&Delta;<sub>vap</sub>S &asymp; 88 J K<sup>-1</sup> mol<sup>-1</sup>', '&Delta;G = &Delta;H - T&Delta;S'], ['r', 'p', 'q', 's'], '<p>Hess: path independence (r). Kirchhoff: how &Delta;H changes with T through &Delta;C<sub>p</sub> (p). &Delta;G&deg; = -RT ln K (q). Trouton: about 88 J K<sup>-1</sup> mol<sup>-1</sup> for many liquids (s). The fifth entry, &Delta;G = &Delta;H - T&Delta;S, is not used.</p>'),
  nat('ct-x20', 3, 'calorimetry', `Propane has &Delta;<sub>f</sub>H = -103.8 kJ mol<sup>-1</sup>; CO<sub>2</sub>(g) -393.5 and H<sub>2</sub>O(l) -285.8. Burning 11.0 g of propane (M = 44.0) releases heat that warms 5.00 kg of water. The rise in temperature, in K, is (c = 4.18 J g<sup>-1</sup> K<sup>-1</sup>)`, 26.6, 0.2, 'K', `<p>C<sub>3</sub>H<sub>8</sub> + 5O<sub>2</sub> &rarr; 3CO<sub>2</sub> + 4H<sub>2</sub>O(l). &Delta;<sub>c</sub>H = 3(-393.5) + 4(-285.8) - (-103.8) = -2219.9 kJ mol<sup>-1</sup>.</p><p>Moles = 11.0/44.0 = 0.250, heat = 0.250 &times; 2219.9 = 555.0 kJ.</p><p>&Delta;T = 555000 / (5000 &times; 4.18) = <b>26.6 K</b>.</p>`),
  mk('ct-x21', 3, 'spontaneity and temperature', 'Ice melts spontaneously above 273 K even though melting is endothermic. The reason is that', 'above 273 K the T&Delta;S term outweighs the positive &Delta;H', ['&Delta;S of the surroundings is positive on melting', '&Delta;H becomes negative above 273 K', 'melting is not a spontaneous process but a reversible one'], '<p>For melting &Delta;H &gt; 0 and &Delta;S &gt; 0. &Delta;G = &Delta;H - T&Delta;S becomes negative once T &gt; &Delta;H/&Delta;S = 273 K. The surroundings lose heat, so their entropy falls; &Delta;H does not change sign.</p>'),

  mk('ct-x22', 4, 'enthalpy of neutralisation', 'HF reacts with NaOH with an enthalpy of neutralisation of about -68 kJ mol<sup>-1</sup>, more negative than the strong acid value of -57.1 kJ. The reason is that', 'ionisation of HF is itself exothermic, since the small F<sup>-</sup> ion is very strongly hydrated', ['HF is a stronger acid than HCl', 'HF forms hydrogen bonds with NaOH', 'the neutralisation of HF is not a reaction of H<sup>+</sup> and OH<sup>-</sup>'], '<p>For a weak acid the measured heat = (heat of ionising HA) + (-57.1). Weak acids such as CH<sub>3</sub>COOH need heat to ionise, so the total is less negative (about -55). HF is the exception: hydration of the tiny F<sup>-</sup> releases so much heat that ionisation is exothermic (about -11 kJ), giving about -68 kJ.</p>', 'The usual rule "weak acid, smaller value" fails for HF.'),
  P('ct-x23', 4, 'phase change at non-standard T', 'x1', 'The &Delta;S of the system when 1 mol of supercooled water freezes at 263 K, in J K<sup>-1</sup>, is closest to', '-20.6', ['-22.0', '+20.6', '-21.4'], `<p>For melting, &Delta;S(263) = &Delta;S(273) + &Delta;C<sub>p</sub> ln(263/273) = 22.01 + 37.6 &times; ln(0.9634) = 22.01 - 1.41 = 20.60 J K<sup>-1</sup>.</p><p>Freezing is the reverse: <b>-20.6 J K<sup>-1</sup></b>.</p>`, '-22.0 is the value at 273 K, not 263 K.'),
  P('ct-x24', 4, 'phase change at non-standard T', 'x1', 'The heat released to the surroundings when 1 mol of water freezes at 263 K, in J, is', '5634', ['6010', '6386', '376'], '<p>&Delta;H<sub>fus</sub>(263) = &Delta;H<sub>fus</sub>(273) + &Delta;C<sub>p</sub>(263 - 273) = 6010 + 37.6 &times; (-10) = 5634 J. Freezing releases <b>5634 J</b> (the surroundings receive +5634 J).</p>', 'The water must lose its extra heat capacity; do not use 6010 J.'),
  PN('ct-x25', 4, 'total entropy', 'x1', 'The total entropy change (system + surroundings), in J K<sup>-1</sup> mol<sup>-1</sup>, when 1 mol of water freezes at 263 K is', 0.82, 0.03, 'J K<sup>-1</sup> mol<sup>-1</sup>', '<p>&Delta;S(surroundings) = +5634/263 = +21.42. &Delta;S(system) = -20.60.</p><p>&Delta;S(total) = 21.42 - 20.60 = <b>+0.82 J K<sup>-1</sup> mol<sup>-1</sup></b>. It is positive, so freezing of supercooled water is spontaneous.</p>'),
  PN('ct-x26', 4, '&Delta;G and K', 'x2', 'Find &Delta;G&deg; at 298 K for N<sub>2</sub>O<sub>4</sub>(g) &rarr; 2NO<sub>2</sub>(g), in kJ mol<sup>-1</sup>.', 4.75, 0.03, 'kJ mol<sup>-1</sup>', '<p>&Delta;G&deg; = &Delta;H&deg; - T&Delta;S&deg; = 57200 - 298 &times; 176 = 57200 - 52448 = 4752 J = <b>+4.75 kJ mol<sup>-1</sup></b>.</p>', 'Convert &Delta;H&deg; from kJ to J, or &Delta;S&deg; from J to kJ.'),
  PN('ct-x27', 4, '&Delta;G and K', 'x2', 'The equilibrium constant K at 298 K for the same reaction is (R = 8.314 J K<sup>-1</sup> mol<sup>-1</sup>)', 0.147, 0.005, '', `<p>ln K = -&Delta;G&deg;/RT = -4752 / (8.314 &times; 298) = -1.918, so K = e<sup>-1.918</sup> = <b>0.147</b>.</p>`),
  P('ct-x28', 4, '&Delta;G and temperature', 'x2', 'Assuming &Delta;H&deg; and &Delta;S&deg; stay constant, K = 1 for the reaction at about', '325 K', ['298 K', '176 K', '57.2 K'], '<p>K = 1 means &Delta;G&deg; = 0, so T = &Delta;H&deg;/&Delta;S&deg; = 57200/176 = <b>325 K</b>. Above this temperature K &gt; 1 and NO<sub>2</sub> is favoured.</p>'),
  msq('ct-x29', 4, 'adiabatic process', '<p>An ideal gas expands <b>reversibly and adiabatically</b>. Which statements are correct?</p>', ['q = 0', '&Delta;S(system) = 0', '&Delta;U is negative', 'The gas gains temperature because it absorbs work'], [0, 1, 2], '<p>Adiabatic means q = 0. Reversible gives dS = q<sub>rev</sub>/T = 0. The gas does work at the cost of its internal energy, so &Delta;U &lt; 0 and T falls. The last option is wrong in two ways: the gas does the work, and T falls.</p>'),
  msq('ct-x30', 4, 'spontaneity and temperature', '<p>A reaction has &Delta;H &gt; 0 and &Delta;S &gt; 0. Which statements are correct?</p>', ['It is spontaneous above T = &Delta;H/&Delta;S', '&Delta;G becomes more negative as T increases', 'K increases as T increases', 'It is spontaneous at all temperatures'], [0, 1, 2], '<p>&Delta;G = &Delta;H - T&Delta;S: the slope of &Delta;G against T is -&Delta;S, which is negative, so &Delta;G falls with T and becomes negative above &Delta;H/&Delta;S. K = e<sup>-&Delta;G&deg;/RT</sup> rises. The reaction is spontaneous only at high T, not at all T.</p>'),
  msq('ct-x31', 4, 'entropy', '<p>For which changes does the entropy of the <b>system</b> increase?</p>', ['Ice melting at 273 K', 'CO<sub>2</sub>(g) &rarr; CO<sub>2</sub>(s)', '2KClO<sub>3</sub>(s) &rarr; 2KCl(s) + 3O<sub>2</sub>(g)', 'N<sub>2</sub>(g) + 3H<sub>2</sub>(g) &rarr; 2NH<sub>3</sub>(g)'], [0, 2], '<p>Melting increases disorder, and the KClO<sub>3</sub> decomposition makes 3 mol of gas from solid. Freezing CO<sub>2</sub> and making ammonia from 4 mol of gas reduce the number of gas moles, so entropy decreases.</p>'),
  msq('ct-x32', 4, 'reversible isothermal expansion', '<p>One mole of an ideal gas expands <b>reversibly and isothermally</b> to twice its volume. Which are correct?</p>', ['&Delta;U = 0', '&Delta;H = 0', '&Delta;S(total) = 0', '&Delta;G = 0'], [0, 1, 2], '<p>For an ideal gas U and H depend only on T, so both are zero. A reversible process has &Delta;S(system) + &Delta;S(surroundings) = 0. But &Delta;G = &Delta;H - T&Delta;S = -T&Delta;S = -RT ln 2, which is not zero.</p>'),
  nat('ct-x33', 4, 'heat at constant pressure', '2.0 mol of a gas with C<sub>p,m</sub> = 30 J K<sup>-1</sup> mol<sup>-1</sup> is heated at constant pressure from 300 K to 400 K. The heat absorbed, in kJ, is', 6, 0, 'kJ', '<p>q<sub>p</sub> = &Delta;H = nC<sub>p,m</sub>&Delta;T = 2.0 &times; 30 &times; 100 = 6000 J = <b>6 kJ</b>.</p>'),
  nat('ct-x34', 4, 'Hess law', 'A &rarr; B, &Delta;H = +120 kJ; B &rarr; C, &Delta;H = -300 kJ; C &rarr; D, &Delta;H = +80 kJ. The enthalpy change (kJ) for D &rarr; A is', 100, 0, 'kJ', '<p>A &rarr; D = 120 - 300 + 80 = -100 kJ. The reverse, D &rarr; A, is <b>+100 kJ</b>.</p>', 'Forget the reversal and you get -100.'),
  nat('ct-x35', 4, '&Delta;G&deg; from &Delta;<sub>f</sub>G&deg;', 'For 2Al + Fe<sub>2</sub>O<sub>3</sub> &rarr; Al<sub>2</sub>O<sub>3</sub> + 2Fe, with &Delta;<sub>f</sub>G&deg;(Al<sub>2</sub>O<sub>3</sub>) = -1582 kJ mol<sup>-1</sup> and &Delta;<sub>f</sub>G&deg;(Fe<sub>2</sub>O<sub>3</sub>) = -742 kJ mol<sup>-1</sup>, the magnitude of &Delta;G&deg; in kJ is', 840, 0, 'kJ', '<p>Elements have &Delta;<sub>f</sub>G&deg; = 0. &Delta;G&deg; = (-1582) - (-742) = -840 kJ. Magnitude: <b>840</b>.</p>'),
  nat('ct-x36', 4, 'spontaneity and temperature', 'A reaction has &Delta;H = +30 kJ mol<sup>-1</sup> and &Delta;S = +100 J K<sup>-1</sup> mol<sup>-1</sup>. Above what temperature (K) is it spontaneous?', 300, 0, 'K', '<p>T = &Delta;H/&Delta;S = 30000 / 100 = <b>300 K</b>.</p>', 'Mixing kJ and J gives 0.3 K.'),
  nat('ct-x37', 4, '&Delta;G of a gas', `2.0 mol of an ideal gas is compressed isothermally at 300 K from 1 bar to 10 bar. &Delta;G in kJ is (R = 8.314)`, 11.49, 0.05, 'kJ', `<p>For an ideal gas at constant T, &Delta;G = nRT ln(p<sub>2</sub>/p<sub>1</sub>) = 2.0 &times; 8.314 &times; 300 &times; ln 10 = ${(2 * R * 300 * Math.log(10)).toFixed(0)} J = <b>+11.49 kJ</b>.</p>`),
  nat('ct-x38', 4, 'total entropy', `1.0 mol of an ideal gas at 300 K expands isothermally from 5.0 L to 20 L against a constant external pressure of 1.0 atm. &Delta;S(total) in J K<sup>-1</sup> is (R = 8.314, 1 L atm = 101.3 J)`, 6.46, 0.05, 'J K<sup>-1</sup>', `<p>&Delta;S(system) = R ln(20/5) = 8.314 &times; 1.386 = 11.53 J K<sup>-1</sup> (state function, so use a reversible path).</p><p>Heat taken from the surroundings = work done = 1.0 &times; 15 &times; 101.3 = 1519.5 J (&Delta;U = 0). &Delta;S(surr) = -1519.5/300 = -5.07.</p><p>&Delta;S(total) = 11.53 - 5.07 = <b>+6.46 J K<sup>-1</sup></b>.</p>`),
  { ...mk('ct-x39', 4, 'mixed counting', '<p>How many of these are correct?</p><p>(1) &Delta;U of an ideal gas is zero in every isothermal process.<br>(2) &Delta;H of an ideal gas is zero in every isothermal process.<br>(3) q is zero in every isothermal process.<br>(4) &Delta;S of the system is zero in every adiabatic process.</p>', '2', ['1', '3', '4'], '<p>(1) true: U depends only on T. (2) true: H = U + nRT depends only on T. (3) false: heat flows to keep T constant. (4) false: an irreversible adiabatic process has &Delta;S &gt; 0. Two are correct: <b>2</b>.</p>'), format: 'statements' },
  asr('ct-x40', 4, 'ideal gas', 'For an ideal gas, &Delta;H = &Delta;U in every isothermal process.', 'U and H of an ideal gas depend only on temperature.', 0, '<p>H = U + pV = U + nRT. If T is constant both U and H are unchanged (there are no intermolecular forces to change U on expansion). So A is true and R is why.</p>'),
  stm('ct-x41', 4, 'third law', 'The entropy of a perfect crystalline solid is zero at 0 K.', 'The entropy of a crystal of carbon monoxide is zero at 0 K.', 1, '<p>Statement I is the third law. CO molecules (C&ndash;O dipole is tiny) can freeze in two orientations (CO or OC), leaving some disorder, so solid CO keeps a residual entropy at 0 K. It is not a "perfect" crystal; Statement II is incorrect.</p>'),
  M('ct-x42', 4, 'heat capacities', 'Match the quantity for an ideal gas (rigid molecules, no vibration)', ['C<sub>v,m</sub> of a monatomic gas', 'C<sub>p,m</sub> of a monatomic gas', 'C<sub>p,m</sub> of a diatomic gas', '&gamma; of a monatomic gas'], ['5/3', '(7/2)R', '(3/2)R', '(5/2)R', '7/5'], ['r', 's', 'q', 'p'], '<p>Monatomic: C<sub>v</sub> = (3/2)R (r), C<sub>p</sub> = (5/2)R (s), &gamma; = 5/3 (p). Diatomic (rigid): C<sub>v</sub> = (5/2)R, so C<sub>p</sub> = (7/2)R (q). 7/5 is the &gamma; of a diatomic gas, not used.</p>'),
  M('ct-x43', 4, 'spontaneity and temperature', 'Match the reaction with the temperature range in which it is spontaneous (standard conditions)', ['2H<sub>2</sub>O<sub>2</sub>(l) &rarr; 2H<sub>2</sub>O(l) + O<sub>2</sub>(g)', 'N<sub>2</sub>(g) + 3H<sub>2</sub>(g) &rarr; 2NH<sub>3</sub>(g)', 'N<sub>2</sub>O<sub>4</sub>(g) &rarr; 2NO<sub>2</sub>(g)', '3O<sub>2</sub>(g) &rarr; 2O<sub>3</sub>(g)'], ['Only at high temperature', 'At no temperature', 'At all temperatures', 'Only at low temperature'], ['r', 's', 'p', 'q'], '<p>A: exothermic, makes a gas (&Delta;S &gt; 0): all T. B: exothermic, 4 mol gas to 2 (&Delta;S &lt; 0): low T only. C: bond breaking (&Delta;H &gt; 0), 1 mol to 2 mol (&Delta;S &gt; 0): high T. D: ozone formation is endothermic and &Delta;n<sub>g</sub> = -1: never.</p>'),
  M('ct-x44', 3, 'enthalpy of formation', 'Match the substance with its standard enthalpy of formation (kJ mol<sup>-1</sup>)', ['O<sub>2</sub>(g)', 'C(diamond)', 'H<sub>2</sub>O(l)', 'C<sub>2</sub>H<sub>4</sub>(g)'], ['-285.8', '0', '+52.3', '+1.9'], ['q', 's', 'p', 'r'], '<p>Oxygen is the reference form of oxygen: 0 (q). Diamond is slightly less stable than graphite: +1.9 (s). Liquid water: -285.8 (p). Ethene is endothermic: +52.3 (r).</p>'),
  mk('ct-x45', 4, 'entropy', 'Which order of standard molar entropy at 298 K is correct?', 'C(diamond) &lt; C(graphite) &lt; CO(g) &lt; CO<sub>2</sub>(g)', ['C(graphite) &lt; C(diamond) &lt; CO(g) &lt; CO<sub>2</sub>(g)', 'C(diamond) &lt; C(graphite) &lt; CO<sub>2</sub>(g) &lt; CO(g)', 'CO(g) &lt; CO<sub>2</sub>(g) &lt; C(diamond) &lt; C(graphite)'], '<p>Rigid, tightly bonded diamond has the least entropy (2.4 J K<sup>-1</sup> mol<sup>-1</sup>), then graphite (5.7), then gases. CO<sub>2</sub> (213.8) is bigger than CO (197.7), having more ways to store energy.</p>'),

  msq('ct-x46', 5, 'Born-Haber cycle', '<p>Which statements about the Born&ndash;Haber cycle are correct?</p>', ['The lattice enthalpy (magnitude) of MgO is larger than that of NaF', 'The enthalpy of sublimation of sodium is positive', 'The first electron gain enthalpy of oxygen is positive', 'The second electron gain enthalpy of oxygen is positive'], [0, 1, 3], '<p>MgO has 2+/2- ions of similar size, so it has a much larger lattice enthalpy than NaF. Sublimation needs heat. The first electron gain of O is negative (about -141 kJ mol<sup>-1</sup>); adding a second electron to the negative O<sup>-</sup> costs energy (about +744 kJ mol<sup>-1</sup>), so only the second is positive.</p>'),
  msq('ct-x47', 5, 'irreversible vs reversible adiabatic', '<p>An ideal gas expands from the same initial state to the same final <b>volume</b> in two adiabatic ways, one reversible and one against a constant external pressure (irreversible). Which are correct?</p>', ['The gas does more work in the reversible path', 'The final temperature is higher in the irreversible path', '&Delta;S(system) is zero in both paths', '&Delta;S(universe) is positive in the irreversible path'], [0, 1, 3], '<p>The reversible path uses the maximum pressure at every step, so it does the most work, loses the most U and cools more. The irreversible path ends hotter, and having the same volume but higher T it has a larger entropy: &Delta;S(system) &gt; 0 and &Delta;S(universe) &gt; 0. Option C is true only for the reversible path.</p>'),
  msq('ct-x48', 5, '&Delta;G and K', '<p>Which are correct for a reaction at constant T?</p>', ['If &Delta;G&deg; = 0, then K = 1', 'If Q &lt; K, then &Delta;G &lt; 0', 'If &Delta;G&deg; &lt; 0, the reaction goes forward from any composition', '&Delta;G&deg; depends on the initial concentrations'], [0, 1], '<p>&Delta;G&deg; = -RT ln K, so zero gives K = 1. &Delta;G = RT ln(Q/K), negative when Q &lt; K. A negative &Delta;G&deg; only says K &gt; 1: a mixture with Q &gt; K still moves backward. &Delta;G&deg; refers to the standard state and is fixed at a given T.</p>'),
  msq('ct-x49', 5, 'isobaric heating', '<p>1 mol of an ideal gas is heated reversibly at constant pressure, raising T by &Delta;T. Which are correct?</p>', ['&Delta;H = C<sub>p,m</sub>&Delta;T', 'q = &Delta;U', '&Delta;U = C<sub>v,m</sub>&Delta;T', 'The work done on the gas is -R&Delta;T'], [0, 2, 3], '<p>For an ideal gas &Delta;U = nC<sub>v</sub>&Delta;T and &Delta;H = nC<sub>p</sub>&Delta;T for any process. At constant p, q = &Delta;H (not &Delta;U). Work done on the gas = -p&Delta;V = -nR&Delta;T.</p>'),
  nat('ct-x50', 5, 'enthalpy of solution', 'A salt MX has a lattice enthalpy of +730 kJ mol<sup>-1</sup> (to separate into gaseous ions). The hydration enthalpies of M<sup>+</sup> and X<sup>-</sup> are -390 and -310 kJ mol<sup>-1</sup>. &Delta;<sub>sol</sub>H in kJ mol<sup>-1</sup> is', 30, 0, 'kJ mol<sup>-1</sup>', '<p>MX(s) &rarr; M<sup>+</sup>(g) + X<sup>-</sup>(g): +730. Then hydration: -390 and -310. &Delta;<sub>sol</sub>H = 730 - 390 - 310 = <b>+30 kJ mol<sup>-1</sup></b>.</p>', 'Check the lattice enthalpy sign convention used in the question.'),
  nat('ct-x51', 5, 'Ellingham-type', 'For 2C(s) + O<sub>2</sub>(g) &rarr; 2CO(g), &Delta;H&deg; = -221 kJ and &Delta;S&deg; = +179 J K<sup>-1</sup>. At what temperature (K, nearest 100) does &Delta;G&deg; reach -400 kJ?', 1000, 0, 'K', '<p>&Delta;G&deg; = -221000 - 179T = -400000, so 179T = 179000 and T = <b>1000 K</b>. Because &Delta;S &gt; 0, &Delta;G&deg; becomes more negative as T increases, which is why carbon reduces metal oxides at high T.</p>'),
  nat('ct-x52', 5, 'irreversible adiabatic process', 'One mole of a diatomic ideal gas (C<sub>v</sub> = 5R/2) at 400 K and 8 atm expands adiabatically against a constant external pressure of 1 atm until its pressure equals 1 atm. The final temperature in K is', 300, 0, 'K', '<p>q = 0, so &Delta;U = w: nC<sub>v</sub>(T<sub>2</sub> - T<sub>1</sub>) = -p<sub>ext</sub>(V<sub>2</sub> - V<sub>1</sub>).</p><p>V<sub>2</sub> = RT<sub>2</sub>/1, V<sub>1</sub> = R(400)/8 = 50R. So 2.5R(T<sub>2</sub> - 400) = -R(T<sub>2</sub> - 50).</p><p>2.5T<sub>2</sub> - 1000 = -T<sub>2</sub> + 50, so 3.5T<sub>2</sub> = 1050 and T<sub>2</sub> = <b>300 K</b>.</p>', 'Using T V<sup>&gamma;-1</sup> = constant is only for reversible adiabatic changes.'),
  nat('ct-x53', 4, 'bond enthalpy', 'Data (kJ mol<sup>-1</sup>): sublimation of C(graphite) +716.7; H<sub>2</sub> &rarr; 2H +436 (218 per H atom); &Delta;<sub>f</sub>H of CH<sub>4</sub>(g) = -74.8. The mean C&ndash;H bond enthalpy to the nearest whole number is', 416, 0, 'kJ mol<sup>-1</sup>', '<p>Atomisation of CH<sub>4</sub>: CH<sub>4</sub> &rarr; C(g) + 4H(g) = 716.7 + 4(218) - (-74.8) = 1663.5 kJ.</p><p>Four C&ndash;H bonds: 1663.5/4 = 415.9, so <b>416</b>.</p>'),
  nat('ct-x54', 4, 'spontaneity', '<p>At 300 K, for how many of these (&Delta;H, &Delta;S) pairs is the reaction spontaneous?</p><p>(&minus;100 kJ, &minus;200 J K<sup>-1</sup>); (+50 kJ, +100 J K<sup>-1</sup>); (+50 kJ, +200 J K<sup>-1</sup>); (&minus;10 kJ, &minus;100 J K<sup>-1</sup>); (+20 kJ, &minus;50 J K<sup>-1</sup>); (&minus;5 kJ, +10 J K<sup>-1</sup>)</p>', 3, 0, '', '<p>&Delta;G = &Delta;H - T&Delta;S: -100000 + 60000 = -40000 (yes); 50000 - 30000 = +20000 (no); 50000 - 60000 = -10000 (yes); -10000 + 30000 = +20000 (no); 20000 + 15000 = +35000 (no); -5000 - 3000 = -8000 (yes). Count: <b>3</b>.</p>'),
  nat('ct-x55', 5, 'entropy of mixing', '2.0 mol of gas A and 3.0 mol of gas B (ideal) mix at 300 K and constant total pressure. &Delta;<sub>mix</sub>G in kJ is (R = 8.314)', -8.39, 0.05, 'kJ', `<p>&Delta;<sub>mix</sub>G = RT(n<sub>A</sub> ln x<sub>A</sub> + n<sub>B</sub> ln x<sub>B</sub>) with x<sub>A</sub> = 0.4 and x<sub>B</sub> = 0.6.</p><p>= 2494.2 &times; (2 ln 0.4 + 3 ln 0.6) = 2494.2 &times; (-1.833 - 1.532) = <b>${(R * 300 * (2 * Math.log(0.4) + 3 * Math.log(0.6)) / 1000).toFixed(2)} kJ</b>.</p>`),
  nat('ct-x56', 5, 'pressure dependence of &Delta;G', 'For C(graphite) &rarr; C(diamond), &Delta;G&deg; = +2.9 kJ mol<sup>-1</sup> at 298 K. Densities: graphite 2.25 g cm<sup>-3</sup>, diamond 3.51 g cm<sup>-3</sup> (M = 12.0 g mol<sup>-1</sup>). Ignoring compressibility, the pressure in kbar (1 kbar = 10<sup>8</sup> Pa) at which the two forms are in equilibrium at 298 K is about', 15.1, 0.3, 'kbar', `<p>&Delta;V = 12.0(1/3.51 - 1/2.25) = -1.915 cm<sup>3</sup> mol<sup>-1</sup> = -1.915 &times; 10<sup>-6</sup> m<sup>3</sup>.</p><p>(&part;G/&part;p)<sub>T</sub> = V, so &Delta;G(p) = 2900 + &Delta;V(p - 10<sup>5</sup>) = 0.</p><p>p = 2900 / 1.915 &times; 10<sup>-6</sup> = 1.51 &times; 10<sup>9</sup> Pa = <b>15.1 kbar</b>.</p>`, 'The denser form is favoured at high pressure.'),
  mk('ct-x57', 5, 'third law', 'Which solid is expected to keep a non-zero (residual) entropy as T approaches 0 K?', 'Solid CO, in which molecules freeze in two possible orientations', ['A perfect crystal of argon', 'A perfect crystal of NaCl', 'A perfect crystal of diamond'], '<p>A perfect crystal in a single arrangement has S = 0 at 0 K (third law). In solid CO the C&ndash;O dipole is so small that molecules freeze in a random mix of CO and OC orientations, leaving a residual entropy of about R ln 2 per mole.</p>'),
  mk('ct-x58', 5, 'irreversible work', 'An ideal gas is compressed isothermally from V<sub>1</sub> to V<sub>2</sub>, once reversibly and once in a single step against p<sub>ext</sub> equal to the final pressure. Which is correct?', 'The work done on the gas is larger in the single step; &Delta;U = 0 in both', ['The work done on the gas is the same in both; &Delta;S(system) is the same', 'The work done on the gas is smaller in the single step; &Delta;U = 0 in both', '&Delta;S(system) is larger in the single step; w is the same'], '<p>Compression needs the least work when done reversibly. The single-step path uses the large final pressure from the start, so w is larger. U depends only on T, so &Delta;U = 0 in both; &Delta;S(system) is the same since S is a state function.</p>', 'Reversible work is the <i>minimum</i> in compression and the <i>maximum</i> in expansion.'),
  asr('ct-x59', 5, 'adiabatic process', 'For a reversible adiabatic expansion of an ideal gas, &Delta;S(system) = 0.', 'In any adiabatic process q = 0, so the entropy change of the system is always zero.', 2, '<p>A is true: dS = q<sub>rev</sub>/T and q<sub>rev</sub> = 0. R is false: dS = q/T holds only for reversible paths. In an irreversible adiabatic process q = 0 but &Delta;S(system) &gt; 0.</p>'),
  { ...mk('ct-x60', 5, 'mixed counting', '<p>How many of these are correct?</p><p>(1) &Delta;<sub>r</sub>H is the same at 298 K and 500 K if &Delta;C<sub>p</sub> = 0.<br>(2) &Delta;<sub>f</sub>H&deg; of Br<sub>2</sub>(g) is zero at 298 K.<br>(3) &Delta;<sub>fus</sub>S of ice is exactly the same at 273 K and 263 K.<br>(4) At constant T and p, G is minimum for the system at equilibrium.</p>', '2', ['1', '3', '4'], '<p>(1) Kirchhoff: &Delta;H(T<sub>2</sub>) - &Delta;H(T<sub>1</sub>) = &Delta;C<sub>p</sub>&Delta;T, so true. (2) False: Br<sub>2</sub> is liquid at 298 K, so Br<sub>2</sub>(g) is not the reference form. (3) False: &Delta;S changes with T by &Delta;C<sub>p</sub> ln(T<sub>2</sub>/T<sub>1</sub>). (4) True. Count = <b>2</b>.</p>'), format: 'statements' },
  M('ct-x61', 4, 'work of expansion', 'Match the ideal-gas process with the expression for the work done on the gas', ['Reversible isothermal', 'Constant external pressure (isobaric)', 'Reversible adiabatic', 'Free expansion'], ['nC<sub>v</sub>&Delta;T', 'zero', '-nRT ln(V<sub>2</sub>/V<sub>1</sub>)', '-p&Delta;V'], ['r', 's', 'p', 'q'], '<p>Isothermal reversible: -nRT ln(V<sub>2</sub>/V<sub>1</sub>) (r). Constant p: -p&Delta;V (s). Adiabatic: q = 0, so w = &Delta;U = nC<sub>v</sub>&Delta;T (p). Free expansion: p<sub>ext</sub> = 0 so w = 0 (q).</p>'),
  M('ct-x62', 3, 'Born-Haber cycle', 'Match the Born&ndash;Haber step for NaCl with its equation', ['Sublimation of sodium', 'First ionisation of sodium', '&frac12; &times; dissociation of chlorine', 'Electron gain by chlorine'], ['Cl(g) + e<sup>-</sup> &rarr; Cl<sup>-</sup>(g)', '&frac12;Cl<sub>2</sub>(g) &rarr; Cl(g)', 'Na(g) &rarr; Na<sup>+</sup>(g) + e<sup>-</sup>', 'Na(s) &rarr; Na(g)'], ['s', 'r', 'q', 'p'], '<p>Sublimation: solid to gas atom (s). Ionisation: the gas atom loses an electron (r). Half the Cl&ndash;Cl bond energy makes one Cl atom (q). Electron gain: Cl(g) + e<sup>-</sup> (p).</p>'),
  M('ct-x63', 4, '&Delta;G and K', 'Match the condition with its meaning', ['&Delta;G&deg; &lt; 0', '&Delta;G&deg; = 0', '&Delta;G&deg; &gt; 0', '&Delta;G = 0'], ['K &lt; 1', 'Q = K', 'K &gt; 1', 'K = 1'], ['r', 's', 'p', 'q'], '<p>&Delta;G&deg; = -RT ln K. Negative: K &gt; 1 (r). Zero: K = 1 (s). Positive: K &lt; 1 (p). &Delta;G = 0 (not &Delta;G&deg;) means the mixture is at equilibrium: Q = K (q).</p>'),
  msq('ct-x64', 4, 'enthalpy of neutralisation', '<p>Which statements about enthalpy of neutralisation are correct?</p>', ['One mole of H<sub>2</sub>SO<sub>4</sub> fully neutralised by NaOH releases about 114.2 kJ', 'HF with NaOH releases less heat than -57.1 kJ per mole of water formed', 'CH<sub>3</sub>COOH with NaOH releases less heat than -57.1 kJ per mole of water formed', 'For any strong acid and strong base the value is the same, because the net change is H<sup>+</sup> + OH<sup>-</sup> &rarr; H<sub>2</sub>O'], [0, 2, 3], '<p>Strong acids and bases are fully ionised, so each mole of water formed releases 57.1 kJ; H<sub>2</sub>SO<sub>4</sub> gives two moles of water per mole (114.2 kJ). Ionising a weak acid like CH<sub>3</sub>COOH takes some heat, so less is released. HF is the exception: its ionisation is exothermic, so it releases more (about 68 kJ). Option B is wrong.</p>'),
  msq('ct-x65', 5, 'spontaneity and temperature', '<p>A reaction has &Delta;H&deg; &lt; 0 and &Delta;S&deg; &lt; 0. Which are correct?</p>', ['It is spontaneous below T = &Delta;H&deg;/&Delta;S&deg;', 'K decreases as T rises', '&Delta;G&deg; becomes more negative as T rises', '&Delta;H&deg; changes sign at high T'], [0, 1], '<p>&Delta;G&deg; = &Delta;H&deg; - T&Delta;S&deg; with -&Delta;S&deg; positive: &Delta;G&deg; rises with T, so it is negative only at low T (below &Delta;H&deg;/&Delta;S&deg;), and K = e<sup>-&Delta;G&deg;/RT</sup> falls as T rises (exothermic, Le Chatelier). Neither &Delta;H&deg; nor &Delta;S&deg; changes sign in this model.</p>'),
];
const XGR2 = {
  x1: { title: 'Freezing of supercooled water', passage: '<p>Water can stay liquid below 273 K. Take for melting of ice at 273 K: &Delta;<sub>fus</sub>H = 6010 J mol<sup>-1</sup> (&Delta;<sub>fus</sub>S = 22.01 J K<sup>-1</sup> mol<sup>-1</sup>). Heat capacities: C<sub>p</sub>(water) = 75.3 and C<sub>p</sub>(ice) = 37.7 J K<sup>-1</sup> mol<sup>-1</sup>, constant with T. One mole of supercooled water freezes at 263 K, 1 atm.</p>' },
  x2: { title: 'Dimerisation of NO<sub>2</sub>', passage: '<p>For N<sub>2</sub>O<sub>4</sub>(g) &rarr; 2NO<sub>2</sub>(g) the standard values at 298 K are &Delta;H&deg; = +57.2 kJ mol<sup>-1</sup> and &Delta;S&deg; = +176 J K<sup>-1</sup> mol<sup>-1</sup>.</p>' },
};
Object.assign(XGR, XGR2);
const XGN = [
  { id: 'ct-g16', type: 'nat', level: 4, exams: EX[4], sub: 'Kirchhoff equation',
    make(rng) {
      const H1 = pick(rng, -250, -60, 10); const dCp = pick(rng, -60, 60, 5); const T1 = 298; const T2 = choose(rng, [350, 400, 450, 500, 600]);
      const ans = +(H1 + dCp * (T2 - T1) / 1000).toFixed(2);
      return { q: `A reaction has &Delta;H = ${H1} kJ at ${T1} K and &Delta;C<sub>p</sub> = ${sg(dCp)} J K<sup>-1</sup>. Assuming &Delta;C<sub>p</sub> is constant, find &Delta;H at ${T2} K in kJ.`, answer: ans, tol: 0.05, unit: 'kJ', H1, dCp, T1, T2,
        sol: `<p>Kirchhoff: &Delta;H(T<sub>2</sub>) = &Delta;H(T<sub>1</sub>) + &Delta;C<sub>p</sub>(T<sub>2</sub> - T<sub>1</sub>).</p><p>= ${H1} + (${dCp})(${T2 - T1})/1000 = ${H1} + (${(dCp * (T2 - T1) / 1000).toFixed(2)}) = <b>${ans} kJ</b>.</p>` };
    }, verify: (p) => (p.H1 * 1000 + p.dCp * (p.T2 - p.T1)) / 1000 },
  { id: 'ct-g17', type: 'nat', level: 3, exams: EX[3], sub: '&Delta;G&deg; from &Delta;H and &Delta;S',
    make(rng) {
      const H = pick(rng, -200, 200, 10); const S = pick(rng, -150, 250, 10); const T = choose(rng, [298, 300, 350, 400, 500]);
      const ans = +(H - T * S / 1000).toFixed(2);
      return { q: `A reaction has &Delta;H = ${H} kJ mol<sup>-1</sup> and &Delta;S = ${S} J K<sup>-1</sup> mol<sup>-1</sup>. Find &Delta;G at ${T} K in kJ mol<sup>-1</sup>.`, answer: ans, tol: 0.05, unit: 'kJ mol<sup>-1</sup>', H, S, T,
        sol: `<p>&Delta;G = &Delta;H - T&Delta;S. Convert &Delta;S to kJ: ${S} J = ${S / 1000} kJ.</p><p>&Delta;G = ${H} - ${T} &times; (${S / 1000}) = <b>${ans} kJ mol<sup>-1</sup></b>.</p>` };
    }, verify: (p) => (p.H * 1000 - p.T * p.S) / 1000 },
  { id: 'ct-g18', type: 'nat', level: 4, exams: EX[4], sub: 'spontaneity and temperature',
    make(rng) {
      const S = pick(rng, 50, 250, 10); const T = pick(rng, 250, 900, 50); const H = +(S * T / 1000).toFixed(2);
      return { q: `A reaction has &Delta;H = +${H} kJ mol<sup>-1</sup> and &Delta;S = +${S} J K<sup>-1</sup> mol<sup>-1</sup>. Above what temperature, in K, does it become spontaneous?`, answer: T, tol: 1, unit: 'K', H, S,
        sol: `<p>&Delta;G = 0 at T = &Delta;H/&Delta;S = ${H * 1000} J / ${S} J K<sup>-1</sup> = <b>${T} K</b>. Both &Delta;H and &Delta;S are positive, so the reaction is spontaneous above this T.</p>` };
    }, verify: (p) => p.H * 1000 / p.S },
  { id: 'ct-g19', type: 'nat', level: 5, exams: EX[5], sub: 'total entropy',
    make(rng) {
      const V1 = pick(rng, 2, 6, 1); const k = choose(rng, [2, 3, 4, 5]); const V2 = V1 * k; const T = choose(rng, [300, 350, 400]); const p = choose(rng, [0.5, 1, 1.5, 2]);
      const w = p * (V2 - V1) * 101.3; const ans = +(R * Math.log(k) - w / T).toFixed(2);
      return { q: `1.0 mol of an ideal gas at ${T} K expands isothermally from ${V1} L to ${V2} L against a constant external pressure of ${p} atm. Find &Delta;S(total) in J K<sup>-1</sup>. (R = 8.314; 1 L atm = 101.3 J)`, answer: ans, tol: 0.05, unit: 'J K<sup>-1</sup>', k, T, p, V1, V2,
        sol: `<p>&Delta;S(system) = R ln(${V2}/${V1}) = ${(R * Math.log(k)).toFixed(3)} J K<sup>-1</sup>.</p><p>&Delta;U = 0, so q = -w = ${p} &times; ${V2 - V1} &times; 101.3 = ${w.toFixed(1)} J taken from the surroundings: &Delta;S(surr) = -${(w / T).toFixed(3)}.</p><p>&Delta;S(total) = <b>${ans} J K<sup>-1</sup></b>.</p>` };
    }, verify: (p) => 8.314 * Math.log(p.V2 / p.V1) - p.p * (p.V2 - p.V1) * 101.3 / p.T },
  { id: 'ct-g20', type: 'mcq', level: 3, exams: EX[3], sub: 'sign of entropy change',
    make(rng) {
      const L = [['N<sub>2</sub>O<sub>4</sub>(g) &rarr; 2NO<sub>2</sub>(g)', 'positive'], ['2SO<sub>2</sub>(g) + O<sub>2</sub>(g) &rarr; 2SO<sub>3</sub>(g)', 'negative'], ['CaCO<sub>3</sub>(s) &rarr; CaO(s) + CO<sub>2</sub>(g)', 'positive'], ['H<sub>2</sub>O(g) &rarr; H<sub>2</sub>O(l)', 'negative'], ['NH<sub>4</sub>Cl(s) &rarr; NH<sub>3</sub>(g) + HCl(g)', 'positive'], ['Ag<sup>+</sup>(aq) + Cl<sup>-</sup>(aq) &rarr; AgCl(s)', 'negative']];
      const r = choose(rng, L); const right = r[1];
      const { options, answer } = shuffleOpts(rng, right, ['positive', 'negative', 'zero', 'cannot be predicted'].filter((x) => x !== right));
      return { q: `The sign of &Delta;S(system) for ${r[0]} is`, options, answer, r,
        sol: `<p>Look at the change in disorder, mainly the amount of gas (or freedom of the particles).</p><p>For this change the entropy of the system is <b>${right}</b>.</p>` };
    }, verify: (p) => p.answer },
  { id: 'ct-g21', type: 'mcq', level: 4, exams: EX[4], sub: 'first law',
    make(rng) {
      const q = pick(rng, 50, 400, 10); const w = pick(rng, 20, 300, 10); const kind = choose(rng, ['by', 'on']);
      const dU = kind === 'by' ? q - w : q + w;
      const { options, answer } = shuffleOpts(rng, `${sg(dU)} J`, [`${sg(-dU)} J`, `${sg(q + (kind === 'by' ? w : -w))} J`, `${sg(-(q + (kind === 'by' ? w : -w)))} J`]);
      return { q: `A gas absorbs ${q} J of heat and work of ${w} J is done ${kind} the gas. &Delta;U is`, options, answer, qq: q, w, kind,
        sol: `<p>&Delta;U = q + w with w = ${kind === 'by' ? '-' : '+'}${w} J (work done ${kind} the gas is ${kind === 'by' ? 'negative' : 'positive'}).</p><p>&Delta;U = ${q} ${kind === 'by' ? '-' : '+'} ${w} = <b>${sg(dU)} J</b>.</p>` };
    }, verify: (p) => p.answer },
  { id: 'ct-g22', type: 'nat', level: 4, exams: EX[4], sub: '&Delta;G of a gas',
    make(rng) {
      const n = pick(rng, 1, 4, 0.5); const T = choose(rng, [300, 310, 350, 400]); const pr = choose(rng, [2, 4, 5, 10]);
      const ans = +(n * R * T * Math.log(pr) / 1000).toFixed(2);
      return { q: `${n} mol of an ideal gas at ${T} K is compressed isothermally from 1 bar to ${pr} bar. Find &Delta;G in kJ. (R = 8.314)`, answer: ans, tol: Math.max(0.03, Math.abs(ans) * 0.005), unit: 'kJ', n, T, pr,
        sol: `<p>At constant T, dG = V dp, so &Delta;G = nRT ln(p<sub>2</sub>/p<sub>1</sub>) = ${n} &times; 8.314 &times; ${T} &times; ln ${pr} = <b>${ans} kJ</b>. It is positive: compressing a gas raises its Gibbs energy.</p>` };
    }, verify: (p) => p.n * 8.314 * p.T * Math.log(p.pr) / 1000 },
  { id: 'ct-g23', type: 'nat', level: 5, exams: EX[5], sub: 'irreversible adiabatic process',
    make(rng) {
      const mono = rng() < 0.5; const Cv = mono ? 1.5 : 2.5; const T1 = choose(rng, [320, 400, 480, 560, 640]); const r = choose(rng, [0.5, 0.25, 0.2, 0.125]);
      const T2 = T1 * (Cv + r) / (Cv + 1); const ans = +T2.toFixed(1);
      return { q: `One mole of a ${mono ? 'monatomic' : 'diatomic'} ideal gas at ${T1} K expands adiabatically against a constant external pressure equal to ${r} of its initial pressure, until its pressure is that external pressure. Find the final temperature in K.`, answer: ans, tol: 0.5, unit: 'K', T1, r, Cv,
        sol: `<p>q = 0, so nC<sub>v</sub>(T<sub>2</sub> - T<sub>1</sub>) = -p<sub>2</sub>(V<sub>2</sub> - V<sub>1</sub>). With V<sub>2</sub> = RT<sub>2</sub>/p<sub>2</sub> and V<sub>1</sub> = RT<sub>1</sub>/p<sub>1</sub> and C<sub>v</sub> = ${Cv}R:</p><p>${Cv}(T<sub>2</sub> - ${T1}) = -T<sub>2</sub> + ${r} &times; ${T1}, so T<sub>2</sub> = ${T1}(${Cv} + ${r})/${Cv + 1} = <b>${ans} K</b>.</p>` };
    }, verify: (p) => p.T1 * (p.Cv + p.r) / (p.Cv + 1) },
  { id: 'ct-g24', type: 'nat', level: 3, exams: EX[3], sub: 'calorimetry',
    make(rng) {
      const m = pick(rng, 10, 90, 10); const t = pick(rng, 5, 25, 5);
      const q = m * (2.09 * t + 334 + 4.18 * 100 + 2260) / 1000; const ans = +q.toFixed(2);
      return { q: `How much heat (kJ) is needed to turn ${m} g of ice at -${t} &deg;C into steam at 100 &deg;C? (c<sub>ice</sub> = 2.09, c<sub>water</sub> = 4.18 J g<sup>-1</sup> K<sup>-1</sup>; fusion 334 J g<sup>-1</sup>; vaporisation 2260 J g<sup>-1</sup>)`, answer: ans, tol: 0.05, unit: 'kJ', m, t,
        sol: `<p>Add four steps per gram: warm the ice (2.09 &times; ${t} = ${(2.09 * t).toFixed(1)}), melt it (334), warm the water (4.18 &times; 100 = 418), vaporise (2260). Total = ${(2.09 * t + 334 + 418 + 2260).toFixed(1)} J g<sup>-1</sup>.</p><p>For ${m} g: <b>${ans} kJ</b>.</p>` };
    }, verify: (p) => p.m * (2.09 * p.t + 334 + 418 + 2260) / 1000 },
  { id: 'ct-g25', type: 'mcq', level: 4, exams: EX[4], sub: 'spontaneity and temperature',
    make(rng) {
      const H = pick(rng, -120, 120, 10); let S = pick(rng, -200, 200, 20); const T = choose(rng, [298, 400, 500, 600]);
      if (Math.abs(H - T * S / 1000) < 0.5) S += 20;
      const G = H - T * S / 1000; const right = G < 0 ? 'spontaneous' : 'non-spontaneous';
      const { options, answer } = shuffleOpts(rng, right, ['spontaneous', 'non-spontaneous', 'at equilibrium', 'impossible to say without K'].filter((x) => x !== right));
      return { q: `A reaction has &Delta;H = ${H} kJ mol<sup>-1</sup> and &Delta;S = ${S} J K<sup>-1</sup> mol<sup>-1</sup>. At ${T} K it is`, options, answer, H, S, T, G,
        sol: `<p>&Delta;G = ${H} - ${T}(${S / 1000}) = ${G.toFixed(2)} kJ mol<sup>-1</sup>. ${G < 0 ? 'Negative' : 'Positive'}, so the reaction is <b>${right}</b>.</p>` };
    }, verify: (p) => p.answer },
];

// ---------------------------------------------------------------- Level 5 round (added 2026-11-22)
const V5P = 'ct';
const V5I = [], V5GR = {}, V5G = []; let _v5 = 0, _v5pos = 1;
const V5EX = ['jee-adv'];
const V5A4 = ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'];
const V5S4 = ['Both Statement I and Statement II are correct', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct', 'Both Statement I and Statement II are incorrect'];
const v5id = () => `${V5P}-v5${String(++_v5).padStart(2, '0')}`;
const v5opts = (right, wrongs) => { const pos = (_v5pos++) % 4; const options = [...wrongs]; options.splice(pos, 0, right); return { options, answer: pos }; };
const v5single = (sub, q, right, wrongs, sol, trap, format = 'single', group) => { const o = v5opts(right, wrongs); const it = { id: v5id(), type: 'mcq', level: 5, format, exams: V5EX, sub, q, options: o.options, answer: o.answer, sol, ...(trap ? { trap } : {}), ...(group ? { group } : {}) }; V5I.push(it); return it; };
const v5nat = (sub, q, answer, tol, unit, sol, trap, format, group) => { V5I.push({ id: v5id(), type: 'nat', level: 5, format: format || (tol === 0 ? 'integer' : 'numeric'), exams: V5EX, sub, q, answer, tol, ...(unit ? { unit } : {}), sol, ...(trap ? { trap } : {}), ...(group ? { group } : {}) }); };
const v5msq = (sub, q, options, answer, sol, trap) => { V5I.push({ id: v5id(), type: 'msq', level: 5, format: 'multi', exams: V5EX, sub, q, options, answer, sol, ...(trap ? { trap } : {}) }); };
const v5fixed = (sub, q, options, answer, sol, trap, format) => { V5I.push({ id: v5id(), type: 'mcq', level: 5, format, exams: V5EX, sub, q, options, answer, sol, ...(trap ? { trap } : {}) }); };
const v5asr = (sub, A, R, answer, sol, trap) => v5fixed(sub, `<p><b>Assertion (A):</b> ${A}</p><p><b>Reason (R):</b> ${R}</p>`, V5A4, answer, sol, trap, 'assertion');
const v5stm = (sub, s1, s2, answer, sol, trap) => v5fixed(sub, `<p><b>Statement I:</b> ${s1}</p><p><b>Statement II:</b> ${s2}</p>`, V5S4, answer, sol, trap, 'statements');
const v5match = (sub, title, l1, l2, map, sol, trap) => {
  const gid = `v5m${Object.keys(V5GR).length + 1}`; const L = 'ABCD', Q = 'pqrst';
  V5GR[gid] = { title, list1: l1.map((t, i) => `${L[i]}. ${t}`), list2: l2.map((t, i) => `${Q[i]}. ${t}`) };
  const code = (m) => m.map((x, i) => `${L[i]}-${x}`).join(', ');
  const sw = (a, i, j) => { const b = [...a]; [b[i], b[j]] = [b[j], b[i]]; return b; };
  const wr = [sw(map, 0, 1), sw(map, 1, 2), sw(map, 2, 3), sw(map, 0, 3), sw(map, 0, 2)].map(code).filter((c) => c !== code(map));
  v5single(sub, 'Match the entries of List I with those of List II and choose the correct code.', code(map), wr.slice(0, 3), sol, trap, 'match', gid);
};
const v5passage = (gid, title, passage) => { V5GR[gid] = { title, passage }; };
const v5gen = (g) => V5G.push({ ...g, id: `${V5P}-v5g${V5G.length + 1}`, level: 5, exams: V5EX });
v5nat('entropy of an irreversible process', '<p>One mole of supercooled liquid water at &minus;10 &deg;C (263.15 K) freezes irreversibly at 1 atm, with the surroundings at 263.15 K. Data: &Delta;<sub>fus</sub>H = 6010 J mol<sup>-1</sup> at 273.15 K; C<sub>p</sub>(liquid) = 75.3 and C<sub>p</sub>(ice) = 37.7 J K<sup>-1</sup> mol<sup>-1</sup>, both constant. The total entropy change of system plus surroundings, in J K<sup>-1</sup>, is</p>', 0.81, 0.03, 'J K<sup>-1</sup>',
  '<p>Idea: S is a state function, so build a reversible path for the system: warm the liquid to 273.15 K, freeze it there, cool the ice back. For the surroundings use the real heat released at 263.15 K.</p><p>&Delta;S(system) = 75.3 ln(273.15/263.15) &minus; 6010/273.15 + 37.7 ln(263.15/273.15) = 37.6 &times; 0.03730 &minus; 22.00 = 1.40 &minus; 22.00 = &minus;20.60 J K<sup>-1</sup>.</p><p>Heat released at 263.15 K (Kirchhoff): &Delta;H(263.15) = &minus;6010 + (37.7 &minus; 75.3)(263.15 &minus; 273.15) = &minus;6010 + 376 = &minus;5634 J. &Delta;S(surr) = +5634/263.15 = +21.41 J K<sup>-1</sup>.</p><p>&Delta;S(total) = &minus;20.60 + 21.41 = <b>+0.81 J K<sup>-1</sup></b>, positive, so the freezing is spontaneous.</p>',
  'Using &minus;6010 J as the heat given to the surroundings (instead of the value at &minus;10 &deg;C) gives a wrong, even negative, answer.');
v5nat('entropy of mixing hot and cold', '<p>1.00 mol of water at 300 K is mixed with 1.00 mol of water at 400 K in a thermally insulated container. Take C<sub>p</sub> = 75.3 J K<sup>-1</sup> mol<sup>-1</sup>, constant. The entropy change of the universe in J K<sup>-1</sup> is</p>', 1.55, 0.03, 'J K<sup>-1</sup>',
  '<p>Idea: the final temperature is the mean, 350 K. Each portion changes entropy by nC<sub>p</sub> ln(T<sub>f</sub>/T<sub>i</sub>); the insulated container exchanges no heat with the surroundings, so the surroundings change by 0.</p><p>&Delta;S = 75.3[ln(350/300) + ln(350/400)] = 75.3[0.1542 &minus; 0.1335] = <b>+1.55 J K<sup>-1</sup></b>.</p>',
  'The hot portion loses entropy (negative), the cold portion gains more; the sum is positive. Using the arithmetic mean of 300 and 400 for a single ln term is a common slip.');
v5nat('multi-step expansion', '<p>One mole of an ideal gas at 8.0 atm and 3.0 L expands isothermally in three stages: against a constant external pressure of 4.0 atm until it stops, then against 2.0 atm, then against 1.0 atm. How much more work (in L atm) does the gas do than if it had expanded in one step directly against 1.0 atm?</p>', 15, 0, 'L atm',
  '<p>Idea: P&times;V is constant at constant temperature, so P<sub>1</sub>V<sub>1</sub> = 24 L atm sets every volume: 3.0 L at 8 atm, 6.0 L at 4 atm, 12 L at 2 atm, 24 L at 1 atm.</p><p>Three stages: 4.0(6 &minus; 3) + 2.0(12 &minus; 6) + 1.0(24 &minus; 12) = 12 + 12 + 12 = 36 L atm.</p><p>One stage: 1.0 &times; (24 &minus; 3) = 21 L atm.</p><p>Difference = 36 &minus; 21 = <b>15 L atm</b>. (The reversible work, 24 ln 8 = 49.9 L atm, is the limit as the number of stages grows.)</p>',
  'Each stage uses its own volume change, not the total one. More stages always give more work, approaching the reversible value.');
v5nat('standard states', '<p>At 298 K and 1 bar, how many of these have a standard enthalpy of formation equal to zero? Br<sub>2</sub>(l), I<sub>2</sub>(s), I<sub>2</sub>(g), Hg(l), C(graphite), C(diamond), O<sub>3</sub>(g), S(rhombic), S(monoclinic), Cl<sub>2</sub>(g), N<sub>2</sub>(g), Br<sub>2</sub>(g)</p>', 7, 0, '',
  '<p>Idea: &Delta;<sub>f</sub>H&deg; is zero only for an element in its most stable form (reference state) at the stated temperature.</p><p>Zero: Br<sub>2</sub>(l), I<sub>2</sub>(s), Hg(l), C(graphite), S(rhombic), Cl<sub>2</sub>(g), N<sub>2</sub>(g) = 7.</p><p>Not zero: I<sub>2</sub>(g), C(diamond), O<sub>3</sub>(g), S(monoclinic), Br<sub>2</sub>(g) (each is not the reference form at 298 K): <b>7</b>.</p>',
  'The same element in a different phase or allotrope (I<sub>2</sub>(g), Br<sub>2</sub>(g), diamond) has a non-zero &Delta;<sub>f</sub>H&deg;.');
v5nat('extensive and intensive properties', '<p>How many of these are intensive properties? Density, molar volume, heat capacity of a sample, temperature, pressure, refractive index, mass, specific heat capacity, enthalpy of a sample</p>', 6, 0, '',
  '<p>Idea: an intensive property does not change if the sample is cut in half; an extensive property halves.</p><p>Intensive: density, molar volume, temperature, pressure, refractive index, specific heat capacity = 6.</p><p>Extensive: heat capacity of the sample, mass, enthalpy of the sample. Answer <b>6</b>.</p>',
  'Heat capacity of a sample is extensive; specific heat (per gram) and molar heat capacity are intensive.');
v5msq('&Delta;H and &Delta;U', '<p>At 298 K (RT = 2.48 kJ mol<sup>-1</sup>), with all gases ideal and the volume of solids and liquids ignored, which statements are correct?</p>',
  ['For N<sub>2</sub>(g) + 3H<sub>2</sub>(g) &rarr; 2NH<sub>3</sub>(g), &Delta;H is more negative than &Delta;U by 2RT', 'For CaCO<sub>3</sub>(s) &rarr; CaO(s) + CO<sub>2</sub>(g), &Delta;H &minus; &Delta;U = +RT', 'A bomb calorimeter directly measures &Delta;H of combustion', 'For 2NO(g) + O<sub>2</sub>(g) &rarr; 2NO<sub>2</sub>(g), &Delta;H &minus; &Delta;U = &minus;RT', 'For H<sub>2</sub>(g) + Cl<sub>2</sub>(g) &rarr; 2HCl(g), &Delta;H = &Delta;U'], [0, 1, 3, 4],
  '<p>Idea: &Delta;H = &Delta;U + &Delta;n<sub>g</sub>RT.</p><p>(A) &Delta;n<sub>g</sub> = 2 &minus; 4 = &minus;2, so &Delta;H = &Delta;U &minus; 2RT. Correct. (B) &Delta;n<sub>g</sub> = +1: &Delta;H &minus; &Delta;U = +RT. Correct. (C) False: the bomb has a fixed volume, so it measures &Delta;U (heat at constant volume). (D) &Delta;n<sub>g</sub> = 2 &minus; 3 = &minus;1, so &minus;RT. Correct. (E) &Delta;n<sub>g</sub> = 0, so &Delta;H = &Delta;U. Correct.</p>',
  'A bomb calorimeter gives &Delta;U; converting to &Delta;H needs &Delta;n<sub>g</sub>RT.');
v5msq('Hess&rsquo;s law', '<p>Data (kJ mol<sup>-1</sup>): &Delta;<sub>f</sub>H&deg;(CO<sub>2</sub>) = &minus;393.5; &Delta;<sub>c</sub>H&deg;(CO) = &minus;283.0; &Delta;<sub>f</sub>H&deg;(H<sub>2</sub>O, l) = &minus;285.8; &Delta;<sub>vap</sub>H(H<sub>2</sub>O) = +44.0. Which statements are correct?</p>',
  ['&Delta;<sub>f</sub>H&deg;(CO) = &minus;110.5', '&Delta;<sub>f</sub>H&deg;(H<sub>2</sub>O, g) = &minus;241.8', 'For C(s) + H<sub>2</sub>O(g) &rarr; CO(g) + H<sub>2</sub>(g), &Delta;H&deg; = +131.3', 'For CO(g) + H<sub>2</sub>O(g) &rarr; CO<sub>2</sub>(g) + H<sub>2</sub>(g), &Delta;H&deg; = +41.2', '&Delta;<sub>c</sub>H&deg;(H<sub>2</sub>) = &minus;241.8'], [0, 1, 2],
  '<p>(A) C + &frac12;O<sub>2</sub> &rarr; CO is (C + O<sub>2</sub> &rarr; CO<sub>2</sub>) minus (CO + &frac12;O<sub>2</sub> &rarr; CO<sub>2</sub>): &minus;393.5 + 283.0 = &minus;110.5. Correct.</p><p>(B) H<sub>2</sub>O(l) &rarr; H<sub>2</sub>O(g) adds 44.0: &minus;285.8 + 44.0 = &minus;241.8. Correct.</p><p>(C) &Delta;H&deg; = &Delta;<sub>f</sub>H&deg;(CO) &minus; &Delta;<sub>f</sub>H&deg;(H<sub>2</sub>O, g) = &minus;110.5 + 241.8 = +131.3. Correct.</p><p>(D) &Delta;H&deg; = &minus;393.5 &minus; (&minus;110.5 &minus; 241.8) = &minus;41.2, not +41.2. False.</p><p>(E) The standard enthalpy of combustion of H<sub>2</sub> gives liquid water, so it is &minus;285.8. False.</p>',
  'Sign slips with products minus reactants, and using H<sub>2</sub>O(g) where the standard definition needs H<sub>2</sub>O(l).');
v5msq('resonance energy of benzene', '<p>Enthalpies of hydrogenation in kJ mol<sup>-1</sup>: cyclohexene to cyclohexane &minus;120; 1,3-cyclohexadiene to cyclohexane (2 H<sub>2</sub>) &minus;232; benzene to cyclohexane (3 H<sub>2</sub>) &minus;208. Which statements are correct?</p>',
  ['A hypothetical cyclohexatriene with three isolated C=C bonds would release about 360 kJ mol<sup>-1</sup>', 'The resonance energy of benzene is about 152 kJ mol<sup>-1</sup>', 'C<sub>6</sub>H<sub>6</sub> + H<sub>2</sub> &rarr; 1,3-cyclohexadiene is endothermic by about 24 kJ mol<sup>-1</sup>', 'The &minus;232 value shows 1,3-cyclohexadiene is destabilised compared with two isolated C=C bonds', 'Benzene releases more heat on hydrogenation than the hypothetical cyclohexatriene'], [0, 1, 2],
  '<p>(A) 3 &times; (&minus;120) = &minus;360. Correct.</p><p>(B) Resonance energy = 360 &minus; 208 = 152. Correct.</p><p>(C) &Delta;H = &minus;208 &minus; (&minus;232) = +24, endothermic: the first step breaks the aromatic stabilisation. Correct.</p><p>(D) False: &minus;232 is less negative than 2 &times; (&minus;120) = &minus;240, so conjugation <i>stabilises</i> the diene by about 8 kJ.</p><p>(E) False: benzene releases 208, less than 360.</p>',
  'Aromatic stabilisation makes benzene release less heat than the hypothetical triene, not more.');
v5match('entropy of ideal gas processes', 'One mole of an ideal gas undergoes the processes in List I. Match each with the one statement from List II that is true for it',
  ['Reversible isothermal expansion to twice the volume', 'Free expansion to twice the volume in an insulated vessel', 'Reversible adiabatic compression', 'Reversible isothermal compression to half the volume'],
  ['&Delta;S(surroundings) = &minus;R ln 2', '&Delta;S(universe) &gt; 0', '&Delta;S(system) = 0', '&Delta;S(surroundings) = +R ln 2', '&Delta;S(universe) &lt; 0'], ['p', 'q', 'r', 's'],
  '<p>A: the system gains R ln 2; reversibly the surroundings lose the same, &minus;R ln 2 (p). B: &Delta;S(system) = R ln 2 but no heat flows, so &Delta;S(surr) = 0 and the universe gains R ln 2 &gt; 0 (q). C: q<sub>rev</sub> = 0, so &Delta;S(system) = 0 (r). D: &Delta;S(system) = &minus;R ln 2, so the surroundings gain +R ln 2 (s). No process here makes &Delta;S(universe) negative.</p>',
  'In a reversible process the system and surroundings changes cancel; in the free expansion only the system changes.');
v5match('&Delta;H and &Delta;U', 'At temperature T (gases ideal, liquids ignored in volume) match the reaction with &Delta;H &minus; &Delta;U',
  ['C<sub>2</sub>H<sub>6</sub>(g) + 7/2 O<sub>2</sub>(g) &rarr; 2CO<sub>2</sub>(g) + 3H<sub>2</sub>O(l)', 'C(graphite) + O<sub>2</sub>(g) &rarr; CO<sub>2</sub>(g)', 'C(graphite) + &frac12;O<sub>2</sub>(g) &rarr; CO(g)', 'C<sub>6</sub>H<sub>6</sub>(l) + 15/2 O<sub>2</sub>(g) &rarr; 6CO<sub>2</sub>(g) + 3H<sub>2</sub>O(l)'],
  ['&minus;2.5RT', '0', '+0.5RT', '&minus;1.5RT', '+RT'], ['p', 'q', 'r', 's'],
  '<p>&Delta;H &minus; &Delta;U = &Delta;n<sub>g</sub>RT with only gases counted.</p><p>A: 2 &minus; (1 + 3.5) = &minus;2.5 (p). B: 1 &minus; 1 = 0 (q). C: 1 &minus; 0.5 = +0.5 (r). D: 6 &minus; 7.5 = &minus;1.5 (s).</p>',
  'Liquid water and liquid or solid reactants are left out when counting &Delta;n<sub>g</sub>.');
v5passage('v5p1', 'A bomb calorimeter', '<p>A bomb calorimeter is calibrated by burning 1.22 g of benzoic acid (M = 122 g mol<sup>-1</sup>, &Delta;<sub>c</sub>U = &minus;3227 kJ mol<sup>-1</sup>), which raises its temperature by 2.00 K. In the same calorimeter 0.92 g of ethanol (M = 46 g mol<sup>-1</sup>) is burnt completely: C<sub>2</sub>H<sub>5</sub>OH(l) + 3O<sub>2</sub>(g) &rarr; 2CO<sub>2</sub>(g) + 3H<sub>2</sub>O(l); the temperature rises by 1.69 K. Take R = 8.314 J K<sup>-1</sup> mol<sup>-1</sup> and T = 298.15 K.</p>');
v5nat('bomb calorimeter', 'The heat capacity of the calorimeter, in kJ K<sup>-1</sup>, is', 16.1, 0.1, 'kJ K<sup>-1</sup>', '<p>Moles of benzoic acid = 1.22/122 = 0.0100 mol. Heat released = 0.0100 &times; 3227 = 32.27 kJ.</p><p>C = 32.27/2.00 = <b>16.1 kJ K<sup>-1</sup></b>.</p>', 'Remember to convert grams to moles first; the &Delta;<sub>c</sub>U is per mole.', 'passage', 'v5p1');
v5nat('bomb calorimeter', 'The standard enthalpy of combustion of ethanol, &Delta;<sub>c</sub>H, in kJ mol<sup>-1</sup>, is about', -1366, 2, 'kJ mol<sup>-1</sup>', '<p>Heat released by 0.92 g ethanol = 16.135 &times; 1.69 = 27.27 kJ for 0.92/46 = 0.0200 mol, so &Delta;<sub>c</sub>U = &minus;27.27/0.0200 = &minus;1363.4 kJ mol<sup>-1</sup> (constant volume).</p><p>&Delta;n<sub>g</sub> = 2 &minus; 3 = &minus;1, so &Delta;<sub>c</sub>H = &Delta;<sub>c</sub>U + &Delta;n<sub>g</sub>RT = &minus;1363.4 &minus; 2.48 = <b>&minus;1365.9 kJ mol<sup>-1</sup></b>, about &minus;1366.</p>', 'The bomb gives &Delta;U, not &Delta;H; the correction is small here but is the point of the question.', 'passage', 'v5p1');
v5single('&Delta;H and &Delta;U', 'For the combustion of ethanol in this passage,', '&Delta;<sub>c</sub>H is more negative than &Delta;<sub>c</sub>U by about 2.5 kJ mol<sup>-1</sup>', ['&Delta;<sub>c</sub>H is less negative than &Delta;<sub>c</sub>U by about 2.5 kJ mol<sup>-1</sup>', '&Delta;<sub>c</sub>H and &Delta;<sub>c</sub>U are equal', '&Delta;<sub>c</sub>H is more negative than &Delta;<sub>c</sub>U by about 7.4 kJ mol<sup>-1</sup>'], '<p>&Delta;H &minus; &Delta;U = &Delta;n<sub>g</sub>RT = (&minus;1)(8.314 &times; 298.15) J = &minus;2.48 kJ mol<sup>-1</sup>. So &Delta;H = &Delta;U &minus; 2.48: more negative by about 2.5 kJ mol<sup>-1</sup>.</p><p>Option 2 has the sign wrong, option 3 treats &Delta;n<sub>g</sub> as zero, option 4 uses &Delta;n<sub>g</sub> = &minus;3 (counting the reactant oxygen only).</p>', 'Gases are counted on both sides: oxygen consumed (3) and carbon dioxide formed (2).', 'passage', 'v5p1');
v5asr('Gibbs energy of a gas', 'At constant temperature the molar Gibbs energy of an ideal gas rises when its pressure is increased.', '(&part;G/&part;P)<sub>T</sub> = V, and the molar volume of a gas is positive.', 0,
  '<p>From dG = V dP &minus; S dT, at constant T we get dG = V dP, so G rises with P because V &gt; 0. For an ideal gas, G = G&deg; + RT ln(P/P&deg;).</p><p>A and R are true and R explains A: <b>option 1</b>.</p>', 'G depends on pressure for gases; the pressure term is what makes &Delta;G differ from &Delta;G&deg; when Q &ne; 1.');
v5single('thermochemistry of neutralisation', 'Which dilute acid, neutralised by dilute NaOH, gives a standard enthalpy of neutralisation more exothermic than the &minus;57 kJ mol<sup>-1</sup> of a strong acid and strong base?', 'HF', ['CH<sub>3</sub>COOH', 'HCN', 'HNO<sub>3</sub>'],
  '<p>For HNO<sub>3</sub> (strong) the value is the basic &minus;57 kJ mol<sup>-1</sup> of H<sup>+</sup> + OH<sup>-</sup> &rarr; H<sub>2</sub>O. A weak acid first has to ionise, which usually costs heat, so CH<sub>3</sub>COOH (about &minus;56) and HCN (about &minus;12) are less exothermic.</p><p>HF is the exception: the small F<sup>-</sup> ion is so strongly hydrated that its ionisation is itself exothermic, giving about &minus;68 kJ mol<sup>-1</sup> in total: <b>HF</b>.</p>', 'A weak acid does not always give a smaller value; hydration of a very small anion can make ionisation exothermic.');

v5gen({ type: 'nat', sub: 'entropy of an irreversible process', make(rng) {
  const d = choose(rng, [5, 8, 10, 12, 15, 20]); const T = 273.15 - d; const T0 = 273.15; const Hf = 6010, Cl = 75.3, Cs = 37.7;
  const dH = -Hf + (Cs - Cl) * (T - T0); const dS = Cl * Math.log(T0 / T) - Hf / T0 + Cs * Math.log(T / T0); const tot = dS - dH / T;
  return { q: `One mole of supercooled liquid water at &minus;${d} &deg;C freezes irreversibly at 1 atm with the surroundings at the same temperature. &Delta;<sub>fus</sub>H = 6010 J mol<sup>-1</sup> at 273.15 K; C<sub>p</sub>(liquid) = 75.3 and C<sub>p</sub>(ice) = 37.7 J K<sup>-1</sup> mol<sup>-1</sup>. The total entropy change (system + surroundings) in J K<sup>-1</sup> is`, answer: +tot.toFixed(3), tol: Math.max(0.03, +(0.03 * Math.abs(tot)).toFixed(3)), unit: 'J K<sup>-1</sup>', d,
    sol: `<p>&Delta;H at ${T.toFixed(2)} K = &minus;6010 + (37.7 &minus; 75.3)(${(-d).toFixed(0)}) = ${dH.toFixed(0)} J.</p><p>&Delta;S(system) = 75.3 ln(273.15/${T.toFixed(2)}) &minus; 6010/273.15 + 37.7 ln(${T.toFixed(2)}/273.15) = ${dS.toFixed(2)} J K<sup>-1</sup>; &Delta;S(surr) = ${(-dH / T).toFixed(2)} J K<sup>-1</sup>.</p><p>Total = <b>${tot.toFixed(2)} J K<sup>-1</sup></b>.</p>`, trap: 'The surroundings receive the heat at the lower temperature, not &minus;6010 J.' }; },
  verify: (p) => { const T = 273.15 - p.d; const dH = -6010 + (37.7 - 75.3) * (T - 273.15); const dSsys = 75.3 * Math.log(273.15 / T) - 6010 / 273.15 + 37.7 * Math.log(T / 273.15); return -(dH - T * dSsys) / T; } });
v5gen({ type: 'nat', sub: 'multi-step expansion', make(rng) {
  const PV = choose(rng, [12, 16, 24, 30, 40]); const m = choose(rng, [2, 3, 4]); const V1 = choose(rng, [2, 3, 4]); const P1 = PV / V1;
  const w = PV * (m / 2 - 1 + 2 ** -m);
  return { q: `One mole of an ideal gas at ${P1} atm and ${V1} L expands isothermally in ${m} stages, against external pressures of P<sub>1</sub>/2, P<sub>1</sub>/4 ... down to P<sub>1</sub>/${2 ** m} in turn (P<sub>1</sub> is the starting pressure), each stage ending at equilibrium. How much more work (L atm) does it do than in a single stage straight against P<sub>1</sub>/${2 ** m}?`, answer: +w.toFixed(3), tol: 0.05, unit: 'L atm', PV, m, V1,
    sol: `<p>P<sub>1</sub>V<sub>1</sub> = ${PV} L atm. Each stage k works against P<sub>1</sub>/2<sup>k</sup> while V goes V<sub>1</sub>2<sup>k-1</sup> to V<sub>1</sub>2<sup>k</sup>, giving P<sub>1</sub>V<sub>1</sub>/2 = ${PV / 2} L atm per stage, ${m} stages: ${m * PV / 2} L atm.</p><p>One stage: (P<sub>1</sub>/${2 ** m})(${2 ** m}V<sub>1</sub> &minus; V<sub>1</sub>) = ${(PV * (1 - 2 ** -m)).toFixed(3)} L atm.</p><p>Extra work = <b>${w.toFixed(3)} L atm</b>.</p>`, trap: 'Every stage contributes the same amount here; do not use the total volume change for each stage.' }; },
  verify: (p) => { const P1 = p.PV / p.V1; let V = p.V1, w = 0; for (let k = 1; k <= p.m; k++) { const Pe = P1 / 2 ** k; const Vn = p.PV / Pe; w += Pe * (Vn - V); V = Vn; } const single = (P1 / 2 ** p.m) * (V - p.V1); return w - single; } });
v5gen({ type: 'nat', sub: 'bomb calorimeter', make(rng) {
  const cmp = choose(rng, [['ethanol(l)', 46, -1, 1363], ['benzene(l)', 78, -1.5, 3264], ['naphthalene(s)', 128, -2, 5152], ['methanol(l)', 32, -0.5, 726]]);
  const [name, M, dn, U] = cmp; const n = choose(rng, [0.01, 0.02, 0.05]); const C = choose(rng, [8, 10, 12, 15]); const dT = +(U * n / C).toFixed(2); const m = +(n * M).toFixed(2);
  const dU = -C * dT / n; const dH = dU + dn * 8.314 * 298.15 / 1000;
  return { q: `${m} g of ${name} is burnt completely in a bomb calorimeter of heat capacity ${C} kJ K<sup>-1</sup> (M = ${M} g mol<sup>-1</sup>), and the temperature rises by ${dT} K. The change in moles of gas for the combustion is &Delta;n<sub>g</sub> = ${dn}. Taking R = 8.314 J K<sup>-1</sup> mol<sup>-1</sup> and T = 298.15 K, &Delta;<sub>c</sub>H in kJ mol<sup>-1</sup> is`, answer: +dH.toFixed(1), tol: Math.max(2, +(Math.abs(dH) * 0.005).toFixed(1)), unit: 'kJ mol<sup>-1</sup>', C, dT, m, M, dn,
    sol: `<p>n = ${m}/${M} = ${(m / M).toFixed(4)} mol. Heat released = ${C} &times; ${dT} = ${(C * dT).toFixed(2)} kJ, so &Delta;<sub>c</sub>U = &minus;${(C * dT).toFixed(2)}/${(m / M).toFixed(4)} = ${dU.toFixed(1)} kJ mol<sup>-1</sup>.</p><p>&Delta;<sub>c</sub>H = &Delta;<sub>c</sub>U + &Delta;n<sub>g</sub>RT = ${dU.toFixed(1)} + (${dn})(2.479) = <b>${dH.toFixed(1)} kJ mol<sup>-1</sup></b>.</p>`, trap: 'The bomb gives &Delta;U; add &Delta;n<sub>g</sub>RT (in kJ) to get &Delta;H.' }; },
  verify: (p) => { const n = p.m / p.M; return -p.C * p.dT / n + p.dn * 8.314 * 298.15 / 1000; } });


const V5BASE = {
  topic: 'chemical-thermodynamics',
  groups: {
    ...XGR,
    m1: { title: 'Match the process of an ideal gas with its feature', list1: ['A. Isothermal process', 'B. Adiabatic process', 'C. Isochoric process', 'D. Isobaric process'], list2: ['p. q = 0', 'q. &Delta;U = 0', 'r. Work of expansion = 0', 's. q = &Delta;H'] },
    m2: { title: 'Match the signs of &Delta;H and &Delta;S with spontaneity', list1: ['A. &Delta;H negative, &Delta;S positive', 'B. &Delta;H positive, &Delta;S negative', 'C. &Delta;H negative, &Delta;S negative', 'D. &Delta;H positive, &Delta;S positive'], list2: ['p. Never spontaneous', 'q. Spontaneous at all temperatures', 'r. Spontaneous at low temperature only', 's. Spontaneous at high temperature only'] },
    m3: { title: 'Match the enthalpy term with its process', list1: ['A. Enthalpy of atomisation of chlorine', 'B. Enthalpy of sublimation of iodine', 'C. Enthalpy of combustion of methane', 'D. Enthalpy of formation of HCl'], list2: ['p. I<sub>2</sub>(s) &rarr; I<sub>2</sub>(g)', 'q. CH<sub>4</sub>(g) + 2O<sub>2</sub>(g) &rarr; CO<sub>2</sub>(g) + 2H<sub>2</sub>O(l)', 'r. &frac12;H<sub>2</sub>(g) + &frac12;Cl<sub>2</sub>(g) &rarr; HCl(g)', 's. &frac12;Cl<sub>2</sub>(g) &rarr; Cl(g)'] },
    m4: { title: 'Match the change with the sign of the entropy change of the system (a code may use a letter more than once)', list1: ['A. Sugar dissolves in water', 'B. Water vapour condenses', 'C. CaCO<sub>3</sub>(s) &rarr; CaO(s) + CO<sub>2</sub>(g)', 'D. 2NO<sub>2</sub>(g) &rarr; N<sub>2</sub>O<sub>4</sub>(g)'], list2: ['p. &Delta;S positive', 'q. &Delta;S negative'] },
    p1: { title: 'A coffee-cup calorimeter', passage: '<p>A student mixes 50 mL of 1.0 M HCl with 50 mL of 1.0 M NaOH in an insulated polystyrene cup. Both solutions start at the same temperature and the mixture warms by <b>6.8 K</b>. Take the density of the solution as 1 g mL<sup>-1</sup> and its specific heat as 4.18 J g<sup>-1</sup> K<sup>-1</sup>. Ignore the heat taken by the cup.</p>' },
    p2: { title: 'Decomposition of limestone', passage: '<p>For CaCO<sub>3</sub>(s) &rarr; CaO(s) + CO<sub>2</sub>(g), the standard values are &Delta;H&deg; = +178 kJ mol<sup>-1</sup> and &Delta;S&deg; = +161 J K<sup>-1</sup> mol<sup>-1</sup>. Assume both stay constant with temperature.</p>' },
    p3: { title: 'Three ways to expand a gas', passage: '<p>One mole of an ideal gas at 300 K and 10 atm is allowed to expand to a final pressure of 1 atm in two ways. <b>Path X:</b> isothermal and reversible. <b>Path Y:</b> isothermal, in one step against a constant external pressure of 1 atm. Take R = 8.314 J K<sup>-1</sup> mol<sup>-1</sup>.</p>' },
  },
  items: [
    // ---------- Level 1 ----------
    mk('ct-001', 1, 'systems', 'A system that can exchange both matter and energy with its surroundings is called', 'an open system', ['a closed system', 'an isolated system', 'an adiabatic system'], '<p>Open: matter and energy both cross the boundary (an open cup of tea). Closed: only energy crosses. Isolated: nothing crosses.</p>'),
    mk('ct-002', 1, 'state functions', 'Which one of the following is a state function?', 'Enthalpy', ['Heat absorbed', 'Work done', 'Heat lost in a given path'], '<p>A state function depends only on the present state of the system, not on how it got there. Enthalpy, internal energy, entropy and Gibbs energy are state functions. Heat and work depend on the path.</p>'),
    mk('ct-003', 1, 'systems', 'Hot tea kept in a tightly closed, ordinary steel flask is best described as', 'a closed system', ['an open system', 'an isolated system', 'an adiabatic isolated system'], '<p>The lid stops matter from leaving, but steel conducts heat, so energy can still pass. Matter fixed, energy exchange allowed: <b>closed</b>.</p>'),
    mk('ct-004', 1, 'first law', 'A gas absorbs 50 J of heat and does 20 J of work on the surroundings. Its change in internal energy is', '+30 J', ['+70 J', '-30 J', '-70 J'], '<p>&Delta;U = q + w with the IUPAC sign rule. q = +50 J (absorbed). Work done <i>by</i> the gas is negative: w = -20 J. So &Delta;U = 50 - 20 = <b>+30 J</b>.</p>', 'Using w = +20 J gives 70 J.'),
    mk('ct-005', 1, 'enthalpy', 'For an exothermic reaction at constant pressure, the sign of &Delta;H is', 'negative', ['positive', 'zero', 'positive or negative depending on volume'], '<p>An exothermic reaction gives heat to the surroundings, so the enthalpy of the system falls: &Delta;H &lt; 0.</p>'),
    mk('ct-006', 1, 'enthalpy of formation', 'Which one of these does <b>not</b> have a standard enthalpy of formation equal to zero?', 'Br<sub>2</sub>(g)', ['O<sub>2</sub>(g)', 'C(graphite)', 'Hg(l)'], '<p>The standard enthalpy of formation of an element is zero only in its most stable form at 1 bar and the given temperature. At 298 K bromine is a liquid, so Br<sub>2</sub>(l) is zero but Br<sub>2</sub>(g) is not (+30.9 kJ mol<sup>-1</sup>).</p>'),
    mk('ct-007', 1, 'entropy', 'The SI unit of molar entropy is', 'J K<sup>-1</sup> mol<sup>-1</sup>', ['J mol<sup>-1</sup>', 'kJ mol<sup>-1</sup>', 'J K mol<sup>-1</sup>'], '<p>Entropy change is heat divided by temperature (q/T), so its unit is J K<sup>-1</sup>; per mole, J K<sup>-1</sup> mol<sup>-1</sup>.</p>'),
    mk('ct-008', 1, 'Gibbs energy', 'At constant temperature and pressure a process is spontaneous when', '&Delta;G is negative', ['&Delta;G is positive', '&Delta;H is always negative', '&Delta;S of the system is always positive'], '<p>The criterion is &Delta;G = &Delta;H - T&Delta;S &lt; 0. A spontaneous process need not be exothermic, nor need the system&rsquo;s entropy rise; the two terms compete.</p>'),
    mk('ct-009', 1, 'properties', 'Which of the following is an intensive property?', 'Density', ['Mass', 'Volume', 'Heat capacity'], '<p>Intensive properties do not depend on the amount of matter (temperature, pressure, density). Mass, volume, enthalpy and heat capacity are extensive. Molar heat capacity or specific heat would be intensive.</p>'),
    mk('ct-010', 1, 'work', 'The work done by an ideal gas expanding into a vacuum (free expansion) is', 'zero', ['positive and equal to nRT', 'negative and equal to nRT', 'equal to P&Delta;V with the gas pressure'], '<p>Work against the surroundings is w = -P<sub>ext</sub>&Delta;V. In a vacuum P<sub>ext</sub> = 0, so w = 0, however much the gas expands.</p>'),
    mk('ct-011', 1, 'third law', 'According to the third law of thermodynamics, the entropy of a perfectly crystalline substance at absolute zero is', 'zero', ['1 J K<sup>-1</sup> mol<sup>-1</sup>', 'infinite', 'equal to R'], '<p>A perfect crystal at 0 K has only one arrangement, so its entropy is zero. This gives a reference point, so absolute entropies can be listed.</p>'),

    // ---------- Level 2 ----------
    nat('ct-012', 2, '&Delta;H and &Delta;U', 'For 2H<sub>2</sub>(g) + O<sub>2</sub>(g) &rarr; 2H<sub>2</sub>O(l) at 298 K, &Delta;H = -571.6 kJ. Find &Delta;U in kJ. (R = 8.314 J K<sup>-1</sup> mol<sup>-1</sup>)', -564.17, 0.1, 'kJ', '<p>&Delta;H = &Delta;U + &Delta;n<sub>g</sub>RT. Gas moles: products 0, reactants 3, so &Delta;n<sub>g</sub> = -3.</p><p>&Delta;U = &Delta;H - &Delta;n<sub>g</sub>RT = -571.6 - (-3)(8.314)(298)/1000 = -571.6 + 7.43 = <b>-564.17 kJ</b>.</p>', 'Watch the sign: &Delta;n<sub>g</sub> is negative, so &Delta;U is less negative than &Delta;H.'),
    nat('ct-013', 2, 'work of expansion', 'Two moles of an ideal gas at 300 K expand reversibly and isothermally from 1 L to 10 L. Find the work done <b>on</b> the gas in kJ. (R = 8.314, ln 10 = 2.303)', -11.49, 0.05, 'kJ', '<p>Reversible isothermal: w = -nRT ln(V<sub>2</sub>/V<sub>1</sub>).</p><p>w = -(2)(8.314)(300)(2.303) = -11 486 J = <b>-11.49 kJ</b>. The gas does 11.49 kJ of work, so work done <i>on</i> it is negative.</p>'),
    mk('ct-014', 2, 'work of expansion', 'A gas expands from 2 L to 6 L against a constant external pressure of 2 atm. The work done on the gas is (1 L atm = 101.3 J)', '-810 J', ['+810 J', '-8 J', '-1216 J'], '<p>w = -P<sub>ext</sub>&Delta;V = -(2 atm)(4 L) = -8 L atm = -8 &times; 101.3 = <b>-810 J</b>.</p>', 'Option B has the wrong sign; option C uses the final volume 6 L instead of the change in volume.'),
    nat('ct-015', 2, 'Hess law', 'C(graphite) + O<sub>2</sub> &rarr; CO<sub>2</sub> has &Delta;H = -393.5 kJ and CO + &frac12;O<sub>2</sub> &rarr; CO<sub>2</sub> has &Delta;H = -283.0 kJ. Find &Delta;H<sub>f</sub> of CO(g) in kJ mol<sup>-1</sup>.', -110.5, 0.1, 'kJ mol<sup>-1</sup>', '<p>Aim: C + &frac12;O<sub>2</sub> &rarr; CO. Take the first equation and reverse the second:</p><p>C + O<sub>2</sub> &rarr; CO<sub>2</sub> (-393.5)<br>CO<sub>2</sub> &rarr; CO + &frac12;O<sub>2</sub> (+283.0)</p><p>Add: C + &frac12;O<sub>2</sub> &rarr; CO, &Delta;H = -393.5 + 283.0 = <b>-110.5 kJ mol<sup>-1</sup></b>.</p>'),
    mk('ct-016', 2, 'heat capacity', 'For one mole of an ideal gas, C<sub>p</sub> - C<sub>v</sub> equals', 'R', ['R/2', '2R', 'zero'], '<p>At constant pressure the gas must also do expansion work. For 1 mol, &Delta;(PV) = R&Delta;T, so C<sub>p</sub> = C<sub>v</sub> + R.</p>'),
    mk('ct-017', 2, 'enthalpy', 'The heat absorbed by a system at constant volume (only P-V work possible) is equal to', '&Delta;U', ['&Delta;H', '&Delta;G', 'T&Delta;S always'], '<p>&Delta;U = q + w and w = -P&Delta;V = 0 at constant volume, so q<sub>v</sub> = &Delta;U. At constant pressure q<sub>p</sub> = &Delta;H.</p>'),
    mk('ct-018', 2, 'entropy', 'In which change does the entropy of the system <b>decrease</b>?', 'N<sub>2</sub>(g) + 3H<sub>2</sub>(g) &rarr; 2NH<sub>3</sub>(g)', ['CaCO<sub>3</sub>(s) &rarr; CaO(s) + CO<sub>2</sub>(g)', 'Ice melting at 0 &deg;C', 'A gas expanding into a vacuum'], '<p>Entropy tracks freedom. Four moles of gas become two, so disorder falls. The other three all create more disorder: gas formed, liquid from solid, larger volume for the gas.</p>'),
    nat('ct-019', 2, 'bond enthalpy', 'Bond enthalpies (kJ mol<sup>-1</sup>): H-H 436, Cl-Cl 242, H-Cl 431. Find &Delta;H for H<sub>2</sub> + Cl<sub>2</sub> &rarr; 2HCl.', -184, 0.5, 'kJ', '<p>&Delta;H = (bonds broken) - (bonds formed).</p><p>Broken: 436 + 242 = 678. Formed: 2 &times; 431 = 862. &Delta;H = 678 - 862 = <b>-184 kJ</b>.</p>', 'Reversing the subtraction gives +184.'),
    nat('ct-020', 2, 'spontaneity and temperature', 'A reaction has &Delta;H = +30 kJ and &Delta;S = +100 J K<sup>-1</sup>. Above what temperature (in K) does it become spontaneous?', 300, 1, 'K', '<p>&Delta;G = &Delta;H - T&Delta;S = 0 at the changeover: T = &Delta;H/&Delta;S = 30 000 J / 100 J K<sup>-1</sup> = <b>300 K</b>.</p><p>Convert kJ to J first.</p>', 'Mixing kJ and J gives 0.3 K.'),
    mk('ct-021', 2, '&Delta;G and K', 'If the equilibrium constant K of a reaction is greater than 1, then at the standard state', '&Delta;G&deg; is negative', ['&Delta;G&deg; is positive', '&Delta;G&deg; is zero', '&Delta;H&deg; is negative'], '<p>&Delta;G&deg; = -RT ln K. For K &gt; 1, ln K is positive, so &Delta;G&deg; is negative. K says nothing about &Delta;H alone.</p>'),
    mk('ct-022', 2, 'enthalpy of combustion', 'The standard enthalpy of combustion of a substance is always', 'negative', ['positive', 'zero', 'positive for hydrocarbons and negative for others'], '<p>Complete burning in oxygen releases heat for every ordinary substance, so &Delta;<sub>c</sub>H&deg; &lt; 0.</p>'),
    nat('ct-023', 2, 'entropy of fusion', 'The enthalpy of fusion of ice is 6.01 kJ mol<sup>-1</sup> at 273 K. Find the entropy of fusion in J K<sup>-1</sup> mol<sup>-1</sup>.', 22.0, 0.1, 'J K<sup>-1</sup> mol<sup>-1</sup>', '<p>At the melting point the two phases are in equilibrium, so &Delta;G = 0 and &Delta;S = &Delta;H/T.</p><p>&Delta;S = 6010 / 273 = <b>22.0 J K<sup>-1</sup> mol<sup>-1</sup></b>.</p>'),
    mk('ct-024', 2, 'adiabatic process', 'An ideal gas is compressed adiabatically. Which statement is correct?', 'Its temperature rises because work done on it raises its internal energy', ['Its temperature stays constant', 'Its temperature falls because no heat is supplied', 'Its internal energy is unchanged'], '<p>Adiabatic means q = 0, so &Delta;U = w. In compression w is positive, so U and hence T rise. (Think of a bicycle pump getting warm.)</p>'),
    nat('ct-025', 2, 'heat capacity', 'How much heat (in kJ) is needed to warm 36 g of water from 20 &deg;C to 70 &deg;C? (specific heat 4.18 J g<sup>-1</sup> K<sup>-1</sup>)', 7.52, 0.02, 'kJ', '<p>q = m c &Delta;T = 36 &times; 4.18 &times; 50 = 7524 J = <b>7.52 kJ</b>.</p>'),
    nat('ct-026', 2, '&Delta;n<sub>g</sub>', 'For 2C<sub>2</sub>H<sub>6</sub>(g) + 7O<sub>2</sub>(g) &rarr; 4CO<sub>2</sub>(g) + 6H<sub>2</sub>O(l), find &Delta;n<sub>g</sub>.', -5, 0, '', '<p>Count gas moles only. Products: 4 (water is liquid). Reactants: 2 + 7 = 9.</p><p>&Delta;n<sub>g</sub> = 4 - 9 = <b>-5</b>.</p>', 'Counting H<sub>2</sub>O(l) as a gas gives +1.'),
    nat('ct-027', 2, 'entropy of surroundings', 'A reaction at 298 K releases 92 kJ of heat to the surroundings at constant pressure. Find &Delta;S of the surroundings in J K<sup>-1</sup>.', 308.7, 1, 'J K<sup>-1</sup>', '<p>The surroundings receive q = +92 000 J at 298 K. &Delta;S<sub>surr</sub> = -&Delta;H<sub>sys</sub>/T = 92 000 / 298 = <b>+308.7 J K<sup>-1</sup></b>.</p>'),
    asr('ct-028', 2, 'state functions', 'Heat is not a state function.', 'The heat absorbed depends on the path followed between two states.', 0, '<p>Both true. The same change of state can be done reversibly or irreversibly with different q, so q depends on the path. This is exactly why heat cannot be a state function, so R explains A.</p>'),
    stm('ct-029', 2, 'enthalpy of combustion', 'For H<sub>2</sub> + &frac12;O<sub>2</sub> &rarr; H<sub>2</sub>O(l), &Delta;H = &Delta;U + (1/2)RT.', 'The enthalpy of combustion of carbon monoxide equals the enthalpy of formation of CO<sub>2</sub>.', 3, '<p>Statement I: &Delta;n<sub>g</sub> = 0 - 1.5 = -1.5, so &Delta;H = &Delta;U - 1.5RT. Statement I is false.</p><p>Statement II: CO + &frac12;O<sub>2</sub> &rarr; CO<sub>2</sub> is not the formation of CO<sub>2</sub> (formation starts from the elements C and O<sub>2</sub>). II is also false. Both incorrect.</p>', 'Both statements look natural but both fail.'),

    // ---------- Level 3 ----------
    nat('ct-030', 3, 'adiabatic process', 'One mole of a monatomic ideal gas at 300 K expands reversibly and adiabatically to twice its volume. Find the final temperature in K. (&gamma; = 5/3; 2<sup>-2/3</sup> = 0.63)', 189, 1, 'K', '<p>Reversible adiabatic: TV<sup>&gamma;-1</sup> = constant.</p><p>T<sub>2</sub> = T<sub>1</sub>(V<sub>1</sub>/V<sub>2</sub>)<sup>2/3</sup> = 300 &times; (1/2)<sup>0.667</sup> = 300 &times; 0.630 = <b>189 K</b>.</p>'),
    mk('ct-031', 3, 'reversible work', 'An ideal gas goes from the same initial state to the same final state isothermally, once reversibly and once irreversibly. The work done <b>by</b> the gas is', 'greater in the reversible path', ['greater in the irreversible path', 'equal in both paths', 'zero in the reversible path'], '<p>In the reversible path the external pressure is kept almost equal to the gas pressure at every step, so the gas pushes against the largest possible opposing pressure and delivers the <b>maximum work</b>. Work is path-dependent, so options B and C are wrong.</p>'),
    nat('ct-032', 3, 'Born-Haber cycle', 'For KF(s): &Delta;<sub>f</sub>H = -568, sublimation of K = +89, ionisation enthalpy of K = +419, &frac12; bond dissociation of F<sub>2</sub> = +79, electron gain enthalpy of F = -328 (all kJ mol<sup>-1</sup>). Find the magnitude of the lattice enthalpy.', 827, 1, 'kJ mol<sup>-1</sup>', '<p>Born-Haber: &Delta;<sub>f</sub>H = S + IE + &frac12;D + EGE + &Delta;<sub>lattice</sub>H, with lattice enthalpy defined as the energy released when the gaseous ions form the solid.</p><p>&Delta;<sub>lattice</sub>H = -568 - 89 - 419 - 79 + 328 = <b>-827 kJ mol<sup>-1</sup></b>. Magnitude 827.</p>', 'Forgetting to use -328 as a subtraction of a negative number.'),
    nat('ct-033', 3, 'enthalpy of formation', 'Combustion enthalpies (kJ mol<sup>-1</sup>): C(graphite) -393.5, H<sub>2</sub>(g) -285.8, C<sub>2</sub>H<sub>6</sub>(g) -1560. Find &Delta;<sub>f</sub>H of ethane, 2C + 3H<sub>2</sub> &rarr; C<sub>2</sub>H<sub>6</sub>.', -84.4, 0.2, 'kJ mol<sup>-1</sup>', '<p>&Delta;<sub>f</sub>H = &Sigma;(combustion of reactants) - &Sigma;(combustion of products), because the same CO<sub>2</sub> and H<sub>2</sub>O come from both sides.</p><p>= [2(-393.5) + 3(-285.8)] - (-1560) = -787 - 857.4 + 1560 = <b>-84.4 kJ mol<sup>-1</sup></b>.</p>'),
    nat('ct-034', 3, '&Delta;G and K', 'For N<sub>2</sub> + 3H<sub>2</sub> &rarr; 2NH<sub>3</sub>, &Delta;H&deg; = -92.2 kJ and &Delta;S&deg; = -198.7 J K<sup>-1</sup>. Find log K at 298 K. (R = 8.314)', 5.78, 0.05, '', '<p>&Delta;G&deg; = &Delta;H&deg; - T&Delta;S&deg; = -92 200 - 298(-198.7) = -92 200 + 59 213 = -32 987 J.</p><p>log K = -&Delta;G&deg;/(2.303RT) = 32 987 / (2.303 &times; 8.314 &times; 298) = <b>5.78</b>.</p>'),
    nat('ct-035', 3, 'spontaneity and temperature', 'For CaCO<sub>3</sub>(s) &rarr; CaO(s) + CO<sub>2</sub>(g), &Delta;H = +178.3 kJ and &Delta;S = +160.5 J K<sup>-1</sup>. Find the minimum temperature (in K) at which it is spontaneous.', 1111, 3, 'K', '<p>T = &Delta;H/&Delta;S = 178 300 / 160.5 = <b>1111 K</b>.</p>'),
    nat('ct-036', 3, 'calorimetry', '100 mL of 1.0 M HCl is mixed with 100 mL of 1.0 M NaOH in an insulated cup. Heat of neutralisation is -57.1 kJ mol<sup>-1</sup>; take density 1 g mL<sup>-1</sup>, c = 4.18 J g<sup>-1</sup> K<sup>-1</sup>. Find the temperature rise in K.', 6.83, 0.05, 'K', '<p>Moles of water formed = 0.100 mol, so heat = 0.100 &times; 57 100 = 5710 J.</p><p>Mass of solution = 200 g. &Delta;T = 5710 / (200 &times; 4.18) = <b>6.83 K</b>.</p>', 'Using only 100 g of solution gives 13.7 K.'),
    nat('ct-037', 3, 'bomb calorimeter', 'A bomb calorimeter (heat capacity 10.5 kJ K<sup>-1</sup>) burns 1.28 g (0.0100 mol) of naphthalene, C<sub>10</sub>H<sub>8</sub>(s), and warms by 5.00 K at 298 K. Find &Delta;<sub>c</sub>H in kJ mol<sup>-1</sup>. (C<sub>10</sub>H<sub>8</sub> + 12O<sub>2</sub> &rarr; 10CO<sub>2</sub> + 4H<sub>2</sub>O(l); R = 8.314)', -5255, 3, 'kJ mol<sup>-1</sup>', '<p>A bomb has constant volume, so the heat gives &Delta;U: q = 10.5 &times; 5.00 = 52.5 kJ for 0.0100 mol. &Delta;<sub>c</sub>U = -5250 kJ mol<sup>-1</sup>.</p><p>&Delta;n<sub>g</sub> = 10 - 12 = -2. &Delta;H = &Delta;U + &Delta;n<sub>g</sub>RT = -5250 + (-2)(8.314)(298)/1000 = -5250 - 4.96 = <b>-5255 kJ mol<sup>-1</sup></b>.</p>', 'The bomb measures &Delta;U, not &Delta;H.'),
    nat('ct-038', 3, 'entropy of expansion', 'Find the entropy change of 1 mol of an ideal gas that expands from 10 L to 20 L at constant temperature (any path from the same states). (R = 8.314)', 5.76, 0.05, 'J K<sup>-1</sup>', '<p>Entropy is a state function, so &Delta;S = nR ln(V<sub>2</sub>/V<sub>1</sub>) = 8.314 &times; ln 2 = 8.314 &times; 0.693 = <b>5.76 J K<sup>-1</sup></b>.</p>'),
    nat('ct-039', 3, 'entropy of heating', 'Two moles of a monatomic ideal gas are heated from 300 K to 600 K at constant pressure. Find &Delta;S in J K<sup>-1</sup>. (C<sub>p</sub> = 5R/2)', 28.8, 0.2, 'J K<sup>-1</sup>', '<p>&Delta;S = nC<sub>p</sub> ln(T<sub>2</sub>/T<sub>1</sub>) = 2 &times; 2.5 &times; 8.314 &times; ln 2 = 41.57 &times; 0.693 = <b>28.8 J K<sup>-1</sup></b>.</p>'),
    nat('ct-040', 3, 'bond enthalpy', 'The enthalpy of atomisation of methane is 1665 kJ mol<sup>-1</sup>. Find the average C-H bond enthalpy in kJ mol<sup>-1</sup>.', 416, 1, 'kJ mol<sup>-1</sup>', '<p>CH<sub>4</sub>(g) &rarr; C(g) + 4H(g) breaks four C-H bonds. Average bond enthalpy = 1665/4 = <b>416.25 kJ mol<sup>-1</sup></b>.</p>', 'This is an average; the four successive dissociation enthalpies are not equal.'),
    nat('ct-041', 3, 'bond enthalpy', 'Bond enthalpies (kJ mol<sup>-1</sup>): C=C 614, C-C 347, C-H 414, H-H 436. Find &Delta;H for C<sub>2</sub>H<sub>4</sub> + H<sub>2</sub> &rarr; C<sub>2</sub>H<sub>6</sub>.', -125, 1, 'kJ', '<p>Broken: C=C (614) + H-H (436) = 1050. Formed: C-C (347) + 2 C-H (828) = 1175.</p><p>&Delta;H = 1050 - 1175 = <b>-125 kJ</b>. (C-H bonds already in ethene stay and cancel.)</p>'),
    nat('ct-042', 3, 'spontaneity and temperature', 'For a reaction, &Delta;G&deg; = 60 - 0.2T kJ mol<sup>-1</sup> (T in K). Find the temperature (K) at which &Delta;G&deg; = 0.', 300, 1, 'K', '<p>60 - 0.2T = 0 gives T = 60/0.2 = <b>300 K</b>. Here &Delta;H&deg; = +60 kJ and &Delta;S&deg; = +0.2 kJ K<sup>-1</sup>.</p>'),
    nat('ct-043', 3, 'mixed', 'The enthalpy of combustion of hydrogen is -286 kJ mol<sup>-1</sup>. How much heat (kJ) is released on burning 5.6 L of H<sub>2</sub> measured at STP (22.4 L mol<sup>-1</sup>)?', 71.5, 0.1, 'kJ', '<p>Moles = 5.6/22.4 = 0.25 mol. Heat = 0.25 &times; 286 = <b>71.5 kJ</b> released.</p>', 'Mixed with mole concept.'),
    nat('ct-044', 3, 'mixed', 'The enthalpy of combustion of methane is -890 kJ mol<sup>-1</sup>. If 1.6 g of methane is burnt and all the heat warms water by 20 K (c = 4.18 J g<sup>-1</sup> K<sup>-1</sup>), what mass of water (g) is warmed? (C = 12, H = 1)', 1065, 5, 'g', '<p>Moles of CH<sub>4</sub> = 1.6/16 = 0.100 mol. Heat = 0.100 &times; 890 = 89 kJ = 89 000 J.</p><p>m = q/(c&Delta;T) = 89 000 / (4.18 &times; 20) = <b>1065 g</b>.</p>', 'Mixed with the mole concept.'),
    nat('ct-045', 3, 'phase equilibrium', 'For a liquid, &Delta;<sub>vap</sub>H = 30 kJ mol<sup>-1</sup> and &Delta;<sub>vap</sub>S = 85 J K<sup>-1</sup> mol<sup>-1</sup>. Estimate its normal boiling point in K.', 353, 1, 'K', '<p>At the boiling point liquid and vapour are in equilibrium: &Delta;G = 0, so T<sub>b</sub> = &Delta;H/&Delta;S = 30 000/85 = <b>353 K</b>.</p>'),
    mk('ct-046', 3, 'heat capacity', 'For an ideal monatomic gas the ratio C<sub>p</sub>/C<sub>v</sub> is', '5/3', ['7/5', '4/3', '3/2'], '<p>C<sub>v</sub> = 3R/2 and C<sub>p</sub> = 5R/2, so &gamma; = 5/3 (about 1.67). Diatomic gas (rotation only): 7/5. Non-linear polyatomic: 4/3.</p>'),
    msq('ct-047', 3, 'cyclic process', 'A system undergoes a cyclic process and returns to its starting state. Which of the following are zero?', ['&Delta;U', '&Delta;H', 'Heat absorbed q', '&Delta;S of the system'], [0, 1, 3], '<p>State functions (U, H, S, G) return to their starting values, so their changes are zero. Heat and work are path functions; in a cycle q = -w, and q need not be zero.</p>', 'Only q and w can be non-zero.'),
    msq('ct-048', 3, 'state functions', 'Select the state functions.', ['Internal energy', 'Work done by the gas', 'Gibbs energy', 'Heat absorbed'], [0, 2], '<p>U and G depend only on the state. Work and heat depend on the path.</p>'),
    asr('ct-049', 3, 'spontaneity', 'The entropy of the universe increases in every spontaneous process.', 'The entropy of the system always increases in a spontaneous process.', 2, '<p>A is true: second law, &Delta;S<sub>total</sub> = &Delta;S<sub>sys</sub> + &Delta;S<sub>surr</sub> &gt; 0.</p><p>R is false: water freezing below 0 &deg;C is spontaneous although the entropy of the water falls; the heat released raises the entropy of the surroundings more.</p>', 'The system alone can lose entropy.'),
    asr('ct-050', 3, 'work of expansion', 'The work done by a gas in a reversible isothermal expansion is more than in an irreversible one between the same two states.', 'In a reversible process the entropy change of the universe is zero.', 1, '<p>Both are true. A holds because the opposing pressure stays almost equal to the gas pressure, so the gas delivers the maximum work. R is a true fact about reversible processes but does not explain why more work is obtained.</p>'),
    stm('ct-051', 3, 'spontaneity', 'A spontaneous process is always exothermic.', 'Melting of ice at 10 &deg;C is spontaneous although it is endothermic.', 2, '<p>Statement I is false: spontaneity needs &Delta;G &lt; 0, and an increase of entropy can outweigh a positive &Delta;H at a high enough temperature.</p><p>Statement II is true: &Delta;H &gt; 0 but T&Delta;S &gt; &Delta;H above 0 &deg;C.</p>', 'The famous misconception: spontaneous means exothermic.'),
    mat('ct-052', 3, 'processes of an ideal gas', 'm1', 'Match List I with List II. Choose the correct code.', 'A-q, B-p, C-r, D-s', ['A-p, B-q, C-r, D-s', 'A-q, B-p, C-s, D-r', 'A-r, B-p, C-q, D-s'], '<p>Isothermal: T constant, so &Delta;U = 0 for an ideal gas (q). Adiabatic: no heat exchange, q = 0 (p). Isochoric: &Delta;V = 0, so no expansion work (r). Isobaric: q<sub>p</sub> = &Delta;H (s).</p>'),
    mat('ct-053', 3, 'spontaneity', 'm2', 'Match List I with List II. Choose the correct code.', 'A-q, B-p, C-r, D-s', ['A-p, B-q, C-r, D-s', 'A-q, B-p, C-s, D-r', 'A-r, B-s, C-q, D-p'], '<p>&Delta;G = &Delta;H - T&Delta;S. A: both terms make &Delta;G negative: always (q). B: both make it positive: never (p). C: -|&Delta;H| + T|&Delta;S|, negative only when T is small (r). D: +|&Delta;H| - T|&Delta;S|, negative only when T is large (s).</p>'),

    // ---------- Level 4 ----------
    nat('ct-054', 4, 'irreversible adiabatic process', 'One mole of a monatomic ideal gas at 10 atm and 300 K expands adiabatically against a constant external pressure of 1 atm until its pressure is 1 atm. Find the final temperature in K.', 192, 1, 'K', '<p>Adiabatic, so &Delta;U = w. nC<sub>v</sub>(T<sub>2</sub> - T<sub>1</sub>) = -P<sub>2</sub>(V<sub>2</sub> - V<sub>1</sub>).</p><p>With V<sub>2</sub> = RT<sub>2</sub>/P<sub>2</sub> and V<sub>1</sub> = RT<sub>1</sub>/P<sub>1</sub>: 1.5R(T<sub>2</sub> - T<sub>1</sub>) = -R(T<sub>2</sub> - T<sub>1</sub>P<sub>2</sub>/P<sub>1</sub>).</p><p>2.5T<sub>2</sub> = T<sub>1</sub>(1.5 + 0.1) = 480, so T<sub>2</sub> = <b>192 K</b>.</p>', 'Using TV^(gamma-1) = const (reversible) gives 119 K, which is wrong here.'),
    nat('ct-055', 4, 'adiabatic process', 'A diatomic ideal gas (&gamma; = 1.4) at 300 K is compressed reversibly and adiabatically until its pressure is doubled. Find the final temperature in K. (2<sup>0.286</sup> = 1.219)', 366, 1, 'K', '<p>Reversible adiabatic: T<sup>&gamma;</sup>P<sup>1-&gamma;</sup> = constant, so T<sub>2</sub>/T<sub>1</sub> = (P<sub>2</sub>/P<sub>1</sub>)<sup>(&gamma;-1)/&gamma;</sup>.</p><p>(&gamma;-1)/&gamma; = 0.4/1.4 = 0.286. T<sub>2</sub> = 300 &times; 2<sup>0.286</sup> = 300 &times; 1.219 = <b>366 K</b>.</p>'),
    nat('ct-056', 4, 'Born-Haber cycle', 'For MgCl<sub>2</sub>(s) (all kJ mol<sup>-1</sup>): &Delta;<sub>f</sub>H = -641, sublimation of Mg = +148, IE<sub>1</sub> + IE<sub>2</sub> of Mg = 738 + 1451, bond dissociation of Cl<sub>2</sub> = +244, electron gain enthalpy of Cl = -349. Find the magnitude of the lattice enthalpy.', 2524, 2, 'kJ mol<sup>-1</sup>', '<p>One Mg and <b>one</b> Cl<sub>2</sub> (two Cl atoms) are needed. Energy needed to reach gaseous ions: 148 + (738 + 1451) + 244 + 2(-349) = 148 + 2189 + 244 - 698 = 1883 kJ.</p><p>&Delta;<sub>lattice</sub>H = &Delta;<sub>f</sub>H - 1883 = -641 - 1883 = <b>-2524 kJ mol<sup>-1</sup></b>.</p>', 'Remember to double the electron gain enthalpy and use the full bond dissociation enthalpy of Cl<sub>2</sub>.'),
    nat('ct-057', 4, 'Kirchhoff equation', 'For N<sub>2</sub> + 3H<sub>2</sub> &rarr; 2NH<sub>3</sub>, &Delta;H = -92.0 kJ at 298 K and &Delta;C<sub>p</sub> = -45.3 J K<sup>-1</sup>. Find &Delta;H at 500 K in kJ, taking &Delta;C<sub>p</sub> constant.', -101.2, 0.2, 'kJ', '<p>Kirchhoff: &Delta;H<sub>2</sub> = &Delta;H<sub>1</sub> + &Delta;C<sub>p</sub>(T<sub>2</sub> - T<sub>1</sub>).</p><p>= -92.0 + (-45.3 &times; 202)/1000 = -92.0 - 9.15 = <b>-101.2 kJ</b>.</p>'),
    nat('ct-058', 4, 'entropy of mixing', 'One mole of ideal gas A and one mole of ideal gas B, each in its own vessel of volume V at the same temperature and pressure, are allowed to mix by joining the vessels (total volume 2V, same T). Find &Delta;S of mixing in J K<sup>-1</sup>. (R = 8.314, ln 2 = 0.693)', 11.53, 0.05, 'J K<sup>-1</sup>', '<p>Each gas doubles its volume (V to 2V) at constant T. &Delta;S for each = R ln 2 = 5.763 J K<sup>-1</sup>. Total = 2 &times; 5.763 = <b>11.53 J K<sup>-1</sup></b>.</p>'),
    nat('ct-059', 4, 'irreversible work', 'One mole of an ideal gas at 300 K and 10 atm expands isothermally in a single step against a constant external pressure of 1 atm until it reaches 1 atm. Find the work done <b>by</b> the gas in kJ. (R = 8.314)', 2.245, 0.01, 'kJ', '<p>w<sub>by</sub> = P<sub>ext</sub>(V<sub>2</sub> - V<sub>1</sub>) with V<sub>1</sub> = RT/10 and V<sub>2</sub> = RT/1.</p><p>= RT(1 - 1/10) = 8.314 &times; 300 &times; 0.9 = 2245 J = <b>2.245 kJ</b>. (Reversible would give RT ln 10 = 5.74 kJ.)</p>'),
    nat('ct-060', 4, '&Delta;G and temperature', 'For N<sub>2</sub> + 3H<sub>2</sub> &rarr; 2NH<sub>3</sub>: &Delta;H&deg; = -92.2 kJ, &Delta;S&deg; = -198.7 J K<sup>-1</sup>. Taking both constant, find K at 500 K. (R = 8.314)', 0.179, 0.005, '', '<p>&Delta;G&deg;(500 K) = -92 200 - 500(-198.7) = -92 200 + 99 350 = +7150 J.</p><p>ln K = -7150/(8.314 &times; 500) = -1.720, so K = e<sup>-1.720</sup> = <b>0.179</b>.</p>', 'K falls with temperature for an exothermic reaction.'),
    nat('ct-061', 4, 'total entropy', 'Supercooled water at -10 &deg;C (263 K) freezes spontaneously. Use &Delta;<sub>fus</sub>H = 6010 J mol<sup>-1</sup> and &Delta;<sub>fus</sub>S = 22.01 J K<sup>-1</sup> mol<sup>-1</sup> at 273 K, and C<sub>p</sub>(l) - C<sub>p</sub>(s) = 38.1 J K<sup>-1</sup> mol<sup>-1</sup>. Find the total entropy change of the universe (J K<sup>-1</sup>) for freezing 1 mol at 263 K. (ln(263/273) = -0.03732)', 0.81, 0.03, 'J K<sup>-1</sup>', '<p>For melting at 263 K: &Delta;H<sub>263</sub> = 6010 + 38.1(263 - 273) = 5629 J. &Delta;S<sub>263</sub> = 22.01 + 38.1 ln(263/273) = 22.01 - 1.422 = 20.59 J K<sup>-1</sup>.</p><p>Freezing: &Delta;S<sub>sys</sub> = -20.59. The surroundings take 5629 J: &Delta;S<sub>surr</sub> = 5629/263 = +21.40.</p><p>&Delta;S<sub>total</sub> = 21.40 - 20.59 = <b>+0.81 J K<sup>-1</sup></b> &gt; 0, so freezing is spontaneous.</p>', 'The system entropy falls; only the total counts.'),
    mk('ct-062', 4, 'Gibbs energy', 'At constant temperature and pressure, the maximum non-expansion (useful) work obtainable from a reaction with &Delta;G = -200 kJ is', '200 kJ', ['-200 kJ done on the system', 'equal to &Delta;H', 'zero, as P-V work is the only work possible'], '<p>-&Delta;G is the maximum non-P-V work the system can do at constant T and P. So 200 kJ can be done by the system (for instance, as electrical work in a cell). It is not tied to &Delta;H.</p>'),
    mk('ct-063', 4, 'mixed', 'At 300 K, &Delta;G&deg; = -5.74 kJ mol<sup>-1</sup> (K = 10) and for the same reaction the reaction quotient is Q = 100. Then &Delta;G is closest to (R = 8.314; 2.303RT = 5.74 kJ)', '+5.74 kJ mol<sup>-1</sup>', ['-5.74 kJ mol<sup>-1</sup>', '-11.5 kJ mol<sup>-1</sup>', '0'], '<p>&Delta;G = &Delta;G&deg; + RT ln Q = -5.74 + 2.303RT log 100 = -5.74 + 5.74 &times; 2 = <b>+5.74 kJ mol<sup>-1</sup></b>.</p><p>Q &gt; K, so the reaction would go backwards: positive &Delta;G.</p>', 'Mixed with chemical equilibrium.'),
    asr('ct-064', 4, 'spontaneity and temperature', 'A reaction with positive &Delta;H and positive &Delta;S can be spontaneous.', 'At high temperature T&Delta;S can exceed &Delta;H.', 0, '<p>Both true. &Delta;G = &Delta;H - T&Delta;S becomes negative once T &gt; &Delta;H/&Delta;S. R directly explains A.</p>'),
    asr('ct-065', 4, 'equilibrium', '&Delta;G&deg; of every reaction at equilibrium is zero.', '&Delta;G of a system at equilibrium is zero.', 3, '<p>R is true: at equilibrium there is no drive to change. A is false: &Delta;G&deg; = -RT ln K and is zero only if K = 1. &Delta;G&deg; refers to standard-state mixtures, not to the equilibrium mixture.</p>', 'Mixing up &Delta;G and &Delta;G&deg;.'),
    stm('ct-066', 4, 'bond enthalpy', 'The four successive C-H bond dissociation enthalpies in CH<sub>4</sub> are all equal.', 'The mean C-H bond enthalpy is one quarter of the enthalpy of atomisation of CH<sub>4</sub>.', 2, '<p>I is false: after each H is removed the remaining fragment (CH<sub>3</sub>, CH<sub>2</sub>, CH) has a different bond strength, so successive values differ.</p><p>II is true: it is how the average is defined.</p>'),
    msq('ct-067', 4, 'reversible isothermal expansion', 'One mole of an ideal gas expands reversibly and isothermally from V<sub>1</sub> to V<sub>2</sub>. Which are correct?', ['&Delta;U = 0', 'q = -w', '&Delta;S<sub>system</sub> = R ln(V<sub>2</sub>/V<sub>1</sub>)', '&Delta;S<sub>universe</sub> &gt; 0'], [0, 1, 2], '<p>Ideal gas isothermal: &Delta;U = 0 so q = -w. &Delta;S<sub>sys</sub> = R ln(V<sub>2</sub>/V<sub>1</sub>). For a reversible path the surroundings lose exactly that entropy, so &Delta;S<sub>universe</sub> = 0, not greater than 0.</p>', 'Reversible gives zero total entropy change.'),
    msq('ct-068', 4, 'spontaneity and temperature', 'A reaction has &Delta;H&deg; &lt; 0 and &Delta;S&deg; &lt; 0. Which statements are correct?', ['It is spontaneous at low temperature', 'Its K decreases as temperature rises', '&Delta;G&deg; becomes less negative as T increases', 'It is spontaneous at all temperatures'], [0, 1, 2], '<p>&Delta;G&deg; = -|&Delta;H| + T|&Delta;S|. This is negative at low T, rises with T, and K = e<sup>-&Delta;G&deg;/RT</sup> falls. It is not spontaneous at high T, so D is false.</p>'),
    mat('ct-069', 4, 'enthalpy terms', 'm3', 'Match List I with List II. Choose the correct code.', 'A-s, B-p, C-q, D-r', ['A-p, B-s, C-q, D-r', 'A-s, B-p, C-r, D-q', 'A-r, B-p, C-q, D-s'], '<p>Atomisation gives gaseous atoms: &frac12;Cl<sub>2</sub> &rarr; Cl (s). Sublimation: solid to gas (p). Combustion: burn 1 mol in O<sub>2</sub> (q). Formation: 1 mol of compound from elements in standard states (r).</p>'),
    mat('ct-070', 4, 'entropy', 'm4', 'Match List I with List II (for the system, unless stated). Choose the correct code.', 'A-p, B-q, C-p, D-q', ['A-q, B-p, C-q, D-p', 'A-p, B-p, C-q, D-q', 'A-p, B-q, C-q, D-p'], '<p>Sugar dissolving: disorder rises (&Delta;S &gt; 0). Condensation: gas to liquid, &Delta;S &lt; 0. CaCO<sub>3</sub> decomposition makes gas, &Delta;S &gt; 0. 2NO<sub>2</sub> &rarr; N<sub>2</sub>O<sub>4</sub>: fewer gas molecules, &Delta;S &lt; 0.</p>'),
    PN('ct-071', 4, 'calorimetry', 'p1', 'Find the molar enthalpy of neutralisation from this experiment, as a magnitude in kJ mol<sup>-1</sup>.', 56.8, 0.2, 'kJ mol<sup>-1</sup>', '<p>Heat = m c &Delta;T = 100 &times; 4.18 &times; 6.8 = 2842 J. Water formed = 0.050 &times; 1.0 = 0.050 mol.</p><p>&Delta;H = -2842/0.050 = -56 840 J mol<sup>-1</sup> = <b>-56.8 kJ mol<sup>-1</sup></b>. Magnitude 56.8.</p>'),
    P('ct-072', 4, 'calorimetry', 'p1', 'The student repeats the experiment with 100 mL of 1.0 M HCl and 100 mL of 1.0 M NaOH. The temperature rise is expected to be', 'again about 6.8 K', ['about 13.6 K', 'about 3.4 K', 'about 9.6 K'], '<p>Doubling both volumes doubles the heat released <i>and</i> the mass being heated, so &Delta;T is unchanged. The heat per mole is a property of the reaction, not of the amount used.</p>', 'Heat doubles but so does the mass warmed.'),
    P('ct-073', 4, 'calorimetry', 'p1', 'If 1.0 M ethanoic acid (a weak acid) is used in place of HCl, the magnitude of the temperature rise is', 'smaller, because some energy is used to ionise the acid', ['larger, because ethanoic acid has more atoms', 'the same, because both are monobasic', 'zero, because a weak acid does not react with NaOH'], '<p>The net change H<sup>+</sup> + OH<sup>-</sup> &rarr; H<sub>2</sub>O gives -57.1 kJ, but a weak acid must first ionise, which takes energy (about 1.5 to 2 kJ mol<sup>-1</sup> for ethanoic acid), so the net heat released is smaller.</p>'),
    PN('ct-074', 3, 'spontaneity and temperature', 'p2', 'Find &Delta;G&deg; (kJ mol<sup>-1</sup>) at 298 K.', 130.0, 0.3, 'kJ mol<sup>-1</sup>', '<p>&Delta;G&deg; = &Delta;H&deg; - T&Delta;S&deg; = 178 - 298 &times; 0.161 = 178 - 47.98 = <b>+130.0 kJ mol<sup>-1</sup></b>. Not spontaneous at room temperature.</p>'),
    PN('ct-075', 3, 'spontaneity and temperature', 'p2', 'Find the minimum temperature (K) at which decomposition becomes spontaneous.', 1106, 3, 'K', '<p>T = &Delta;H&deg;/&Delta;S&deg; = 178 000 / 161 = <b>1106 K</b>.</p>'),
    P('ct-076', 3, 'spontaneity and temperature', 'p2', 'At 1200 K the value of &Delta;G&deg; for this decomposition is', 'about -15 kJ mol<sup>-1</sup>, so it is spontaneous', ['about +15 kJ mol<sup>-1</sup>, so it is not spontaneous', 'about +370 kJ mol<sup>-1</sup>', 'about -371 kJ mol<sup>-1</sup>'], '<p>&Delta;G&deg; = 178 - 1200 &times; 0.161 = 178 - 193.2 = <b>-15.2 kJ mol<sup>-1</sup></b>. Negative: spontaneous.</p>', 'Unit trap in options C and D.'),
    PN('ct-077', 4, 'reversible work', 'p3', 'Find the magnitude of the work done by the gas in Path X, in kJ. (ln 10 = 2.303)', 5.74, 0.02, 'kJ', '<p>w = nRT ln(P<sub>1</sub>/P<sub>2</sub>) = 8.314 &times; 300 &times; 2.303 = 5743 J = <b>5.74 kJ</b>.</p>'),
    PN('ct-078', 4, 'irreversible work', 'p3', 'Find the magnitude of the work done by the gas in Path Y, in kJ.', 2.24, 0.01, 'kJ', '<p>w = P<sub>ext</sub>(V<sub>2</sub> - V<sub>1</sub>) = RT(1 - 1/10) = 8.314 &times; 300 &times; 0.9 = 2245 J = <b>2.24 kJ</b>.</p>'),
    P('ct-079', 4, 'entropy', 'p3', 'Compare &Delta;S of the gas in the two paths.', 'It is the same in X and Y, equal to R ln 10, because S is a state function', ['It is larger in X because more work is done', 'It is zero in Y because the process is irreversible', 'It is larger in Y because the process is spontaneous'], '<p>Both paths join the same two states, so &Delta;S<sub>gas</sub> = R ln(P<sub>1</sub>/P<sub>2</sub>) = 19.14 J K<sup>-1</sup> in each. Only &Delta;S of the surroundings (and the total) differs.</p>', 'State function: path does not matter.'),

    // ---------- Level 5 ----------
    nat('ct-080', 5, 'irreversible vs reversible adiabatic', 'Two samples of one mole of a monatomic ideal gas start at 10 atm and 300 K and each expand adiabatically to 1 atm: one reversibly, the other in one step against 1 atm. Find the difference in final temperatures (irreversible minus reversible) in K. (0.1<sup>0.4</sup> = 0.398)', 73, 1, 'K', '<p>Reversible: T<sub>2</sub> = 300 &times; (1/10)<sup>0.4</sup> = 300 &times; 0.398 = 119.4 K.</p><p>Irreversible: 2.5T<sub>2</sub> = 300(1.5 + 0.1), T<sub>2</sub> = 192 K.</p><p>Difference = 192 - 119.4 = <b>72.6 K</b>, about 73. The gas does more work in the reversible path, so it cools more.</p>'),
    asr('ct-081', 5, 'adiabatic expansion', 'For the same initial state and the same final pressure, a reversible adiabatic expansion of an ideal gas gives a lower final temperature than an irreversible adiabatic expansion.', 'Both processes end at the same temperature because no heat is exchanged in either.', 2, '<p>A is true: since q = 0, &Delta;U = w, and the gas does more work in the reversible path, so it loses more internal energy and cools more.</p><p>R is false: the final temperatures differ (119 K and 192 K in a typical case); that is exactly why A is true.</p>'),
    stm('ct-082', 5, 'free expansion', 'For the free expansion of an ideal gas into a vacuum in a thermally isolated vessel, q = 0, w = 0 and &Delta;U = 0.', 'The temperature of an ideal gas falls in an adiabatic free expansion.', 1, '<p>I is correct. II is incorrect: &Delta;U = 0 and U of an ideal gas depends only on T, so T is unchanged (a real gas would show a small change). Also &Delta;S &gt; 0 because the volume increases.</p>'),
    { id: 'ct-083', type: 'mcq', level: 5, format: 'statements', exams: EX[5], sub: 'second law',
      q: '<p>Consider: (i) &Delta;G&deg; of a reaction depends on temperature; (ii) K of a gas reaction depends on the total pressure; (iii) &Delta;S<sub>surr</sub> = -&Delta;H/T at constant pressure and temperature; (iv) for ideal gases &Delta;H of a reaction at a fixed temperature does not depend on pressure. How many of these statements are correct?</p>',
      options: ['One', 'Two', 'Three', 'Four'], answer: 2,
      sol: '<p>(i) True: &Delta;G&deg; = &Delta;H&deg; - T&Delta;S&deg;. (ii) False: K depends only on temperature; pressure changes only shift the position of equilibrium. (iii) True. (iv) True: ideal gas enthalpy depends on T only. Three are correct.</p>', trap: 'K is changed by temperature alone.' },
    stm('ct-088', 2, '&Delta;H and &Delta;U', 'For N<sub>2</sub>(g) + O<sub>2</sub>(g) &rarr; 2NO(g), &Delta;H = &Delta;U.', '&Delta;H equals &Delta;U for a reaction only when the change in the number of moles of gas is zero (ignoring volume changes of solids and liquids).', 0, '<p>&Delta;H = &Delta;U + &Delta;n<sub>g</sub>RT. For N<sub>2</sub> + O<sub>2</sub> &rarr; 2NO, &Delta;n<sub>g</sub> = 2 - 2 = 0, so I is correct. II states the general rule, which is also correct and explains I.</p>'),
    msq('ct-084', 5, 'adiabatic vs isothermal', 'An ideal gas expands reversibly from the same initial state to the same final <b>volume</b>, once isothermally and once adiabatically. Which are correct for the adiabatic path compared with the isothermal path?', ['The final temperature is lower', 'The work done by the gas is smaller', 'The final pressure is lower', '&Delta;U is zero'], [0, 1, 2], '<p>In the adiabatic path the gas cools as it expands, so T and the final pressure are lower and the area under the P-V curve (work) is smaller. Adiabatic &Delta;U = w &lt; 0, not zero (that is the isothermal case).</p>', 'The adiabatic curve on a P-V graph is steeper.'),
    msq('ct-085', 5, '&Delta;G&deg; against T', 'For a reaction, &Delta;G&deg; (kJ mol<sup>-1</sup>) = 60 - 0.2T. Which statements are correct?', ['&Delta;H&deg; = +60 kJ mol<sup>-1</sup>', '&Delta;S&deg; = +200 J K<sup>-1</sup> mol<sup>-1</sup>', 'The reaction is spontaneous (standard state) above 300 K', 'K &lt; 1 at 400 K'], [0, 1, 2], '<p>Comparing with &Delta;G&deg; = &Delta;H&deg; - T&Delta;S&deg;: &Delta;H&deg; = +60 kJ and &Delta;S&deg; = +0.2 kJ K<sup>-1</sup> = 200 J K<sup>-1</sup>. &Delta;G&deg; &lt; 0 for T &gt; 300 K. At 400 K, &Delta;G&deg; = -20 kJ, so K &gt; 1. D is false.</p>'),
    mk('ct-086', 5, 'heat capacity', 'For an ideal gas with &gamma; = C<sub>p</sub>/C<sub>v</sub> = 4/3 (a non-linear polyatomic gas, all modes except vibration active), the molar C<sub>v</sub> is', '3R', ['5R/2', '3R/2', '4R'], '<p>C<sub>p</sub> - C<sub>v</sub> = R and C<sub>p</sub> = (4/3)C<sub>v</sub> give C<sub>v</sub>/3 = R, so C<sub>v</sub> = <b>3R</b> (3 translational + 3 rotational degrees, each R/2).</p>'),
    nat('ct-087', 5, 'mixed', 'For a reaction at 298 K, &Delta;H&deg; = -40 kJ mol<sup>-1</sup> and &Delta;S&deg; = -100 J K<sup>-1</sup> mol<sup>-1</sup>. Find the temperature (K) above which K becomes less than 1.', 400, 1, 'K', '<p>K = 1 when &Delta;G&deg; = 0: T = &Delta;H&deg;/&Delta;S&deg; = (-40 000)/(-100) = 400 K.</p><p>Above 400 K, &Delta;G&deg; = -40 000 + 100T &gt; 0, so K &lt; 1. Answer <b>400 K</b>.</p>', 'Mixed with chemical equilibrium.'),
    ...XI,
  ],
  gens: [
    { id: 'ct-g01', type: 'nat', level: 2, exams: EX[2], sub: '&Delta;H and &Delta;U',
      make(rng) {
        const r = choose(rng, RX); const dH = pick(rng, -450, -50, 10); const T = choose(rng, [298, 300, 350, 400, 500]);
        const ans = +(dH - r[1] * R * T / 1000).toFixed(2);
        return { q: `For ${r[0]} at ${T} K, &Delta;H = ${dH} kJ. Find &Delta;U in kJ. (R = 8.314 J K<sup>-1</sup> mol<sup>-1</sup>)`, answer: ans, tol: 0.05, unit: 'kJ', dH, dn: r[1], T,
          sol: `<p>&Delta;H = &Delta;U + &Delta;n<sub>g</sub>RT, with &Delta;n<sub>g</sub> = ${r[1]}.</p><p>&Delta;U = ${dH} - (${r[1]})(8.314)(${T})/1000 = ${dH} - (${(r[1] * R * T / 1000).toFixed(3)}) = <b>${ans} kJ</b>.</p>` };
      }, verify: (p) => (p.dH * 1000 - p.dn * 8.314 * p.T) / 1000 },
    { id: 'ct-g02', type: 'nat', level: 3, exams: EX[3], sub: 'work of expansion',
      make(rng) {
        const n = pick(rng, 1, 4, 0.5); const T = pick(rng, 280, 400, 20); const k = choose(rng, [2, 4, 5, 10]);
        const w = -n * R * T * Math.log(k) / 1000; const ans = +w.toFixed(2);
        return { q: `${n} mol of an ideal gas at ${T} K expands reversibly and isothermally to ${k} times its volume. Find the work done <b>on</b> the gas in kJ. (R = 8.314)`, answer: ans, tol: Math.max(0.03, Math.abs(ans) * 0.005), unit: 'kJ', n, T, k,
          sol: `<p>w = -nRT ln(V<sub>2</sub>/V<sub>1</sub>) = -(${n})(8.314)(${T}) ln ${k}</p><p>= -${(n * R * T).toFixed(0)} &times; ${Math.log(k).toFixed(3)} J = <b>${ans} kJ</b> (negative: the gas does the work).</p>` };
      }, verify: (p) => -(p.n * 8.314 * p.T * Math.log(p.k)) / 1000 },
    { id: 'ct-g03', type: 'nat', level: 2, exams: EX[2], sub: 'work of expansion',
      make(rng) {
        const P = pick(rng, 1, 5, 0.5); const V1 = pick(rng, 1, 5, 1); const dV = pick(rng, 2, 10, 1);
        const w = -P * dV * 101.3; const ans = +w.toFixed(0);
        return { q: `A gas expands from ${V1} L to ${V1 + dV} L against a constant external pressure of ${P} atm. Find the work done on the gas in J. (1 L atm = 101.3 J)`, answer: ans, tol: 2, unit: 'J', P, V1, V2: V1 + dV,
          sol: `<p>w = -P<sub>ext</sub>&Delta;V = -(${P})(${V1 + dV} - ${V1}) L atm = -${P * dV} L atm.</p><p>&times; 101.3 = <b>${ans} J</b>.</p>` };
      }, verify: (p) => -p.P * (p.V2 - p.V1) * 101.3 },
    { id: 'ct-g04', type: 'nat', level: 3, exams: EX[3], sub: 'enthalpy of combustion',
      make(rng) {
        const f = choose(rng, FUELS); const [name, c, h, hf] = f; const ans = +(c * -393.5 + (h / 2) * -285.8 - hf).toFixed(1);
        return { q: `Using &Delta;<sub>f</sub>H (kJ mol<sup>-1</sup>): CO<sub>2</sub>(g) -393.5, H<sub>2</sub>O(l) -285.8, ${name}(g) ${sg(hf)}. Find the enthalpy of complete combustion of one mole of ${name} to CO<sub>2</sub>(g) and H<sub>2</sub>O(l).`, answer: ans, tol: 0.3, unit: 'kJ mol<sup>-1</sup>', c, h, hf,
          sol: `<p>${name} + O<sub>2</sub> &rarr; ${c}CO<sub>2</sub> + ${h / 2}H<sub>2</sub>O(l). &Delta;H = &Sigma;&Delta;<sub>f</sub>H(products) - &Sigma;&Delta;<sub>f</sub>H(reactants).</p><p>= [${c}(-393.5) + ${h / 2}(-285.8)] - (${hf}) = <b>${ans} kJ mol<sup>-1</sup></b>. O<sub>2</sub> contributes zero.</p>` };
      }, verify: (p) => p.c * -393.5 + p.h * -142.9 - p.hf },
    { id: 'ct-g05', type: 'nat', level: 2, exams: EX[2], sub: 'bond enthalpy',
      make(rng) {
        const x = choose(rng, HX); const ans = 436 + x[1] - 2 * x[2];
        return { q: `Bond enthalpies (kJ mol<sup>-1</sup>): H-H 436, ${x[0]}-${x[0]} ${x[1]}, H-${x[0]} ${x[2]}. Find &Delta;H for H<sub>2</sub> + ${x[0]}<sub>2</sub> &rarr; 2H${x[0]}.`, answer: ans, tol: 0.5, unit: 'kJ', xx: x[1], hx: x[2],
          sol: `<p>&Delta;H = bonds broken - bonds formed = (436 + ${x[1]}) - 2(${x[2]}) = ${436 + x[1]} - ${2 * x[2]} = <b>${ans} kJ</b>.</p>` };
      }, verify: (p) => (436 + p.xx) - 2 * p.hx },
    { id: 'ct-g06', type: 'nat', level: 2, exams: EX[2], sub: 'Gibbs energy',
      make(rng) {
        const dH = pick(rng, -200, 200, 10); const dS = choose(rng, [-150, -100, -50, 50, 100, 150, 200]); const T = pick(rng, 300, 900, 100);
        const ans = +(dH - T * dS / 1000).toFixed(2);
        return { q: `For a reaction &Delta;H = ${sg(dH)} kJ and &Delta;S = ${sg(dS)} J K<sup>-1</sup>. Find &Delta;G at ${T} K in kJ.`, answer: ans, tol: 0.05, unit: 'kJ', dH, dS, T,
          sol: `<p>&Delta;G = &Delta;H - T&Delta;S. Convert &Delta;S to kJ: ${dS / 1000} kJ K<sup>-1</sup>.</p><p>&Delta;G = ${dH} - (${T})(${dS / 1000}) = ${dH} - (${(T * dS / 1000).toFixed(1)}) = <b>${ans} kJ</b>.</p>` };
      }, verify: (p) => (p.dH * 1000 - p.T * p.dS) / 1000 },
    { id: 'ct-g07', type: 'nat', level: 3, exams: EX[3], sub: 'spontaneity and temperature',
      make(rng) {
        const T = pick(rng, 300, 1500, 50); const dS = pick(rng, 80, 200, 10); const dH = T * dS / 1000;
        return { q: `A reaction has &Delta;H = +${dH} kJ and &Delta;S = +${dS} J K<sup>-1</sup>, both taken as constant. At what minimum temperature (K) is it spontaneous?`, answer: T, tol: 1, unit: 'K', dH, dS,
          sol: `<p>&Delta;G = 0 at T = &Delta;H/&Delta;S = ${dH * 1000} J / ${dS} J K<sup>-1</sup> = <b>${T} K</b>. Above this, T&Delta;S exceeds &Delta;H.</p>` };
      }, verify: (p) => (p.dH * 1000) / p.dS },
    { id: 'ct-g08', type: 'nat', level: 3, exams: EX[3], sub: '&Delta;G and K',
      make(rng) {
        const dG = pick(rng, -40, 30, 5); const T = choose(rng, [298, 300, 310, 350]);
        const ans = +(-dG * 1000 / (2.303 * R * T)).toFixed(2);
        return { q: `The standard Gibbs energy change of a reaction at ${T} K is ${dG} kJ mol<sup>-1</sup>. Find log<sub>10</sub> K. (R = 8.314)`, answer: ans, tol: 0.03, dG, T,
          sol: `<p>&Delta;G&deg; = -2.303RT log K, so log K = -&Delta;G&deg;/(2.303RT) = ${-dG * 1000} / (2.303 &times; 8.314 &times; ${T}) = <b>${ans}</b>.</p>${dG > 0 ? '<p>Positive &Delta;G&deg; gives K &lt; 1, so log K is negative.</p>' : ''}` };
      }, verify: (p) => (-p.dG * 1000) / (Math.LN10 * 8.314 * p.T) },
    { id: 'ct-g09', type: 'nat', level: 3, exams: EX[3], sub: 'entropy of expansion',
      make(rng) {
        const n = pick(rng, 1, 3, 0.5); const V1 = pick(rng, 5, 20, 5); const k = choose(rng, [2, 3, 4, 5, 10]);
        const ans = +(n * R * Math.log(k)).toFixed(2);
        return { q: `${n} mol of an ideal gas expands isothermally from ${V1} L to ${V1 * k} L. Find &Delta;S of the gas in J K<sup>-1</sup>. (R = 8.314)`, answer: ans, tol: Math.max(0.05, ans * 0.005), unit: 'J K<sup>-1</sup>', n, k,
          sol: `<p>&Delta;S = nR ln(V<sub>2</sub>/V<sub>1</sub>) = ${n} &times; 8.314 &times; ln ${k} = ${(n * R).toFixed(3)} &times; ${Math.log(k).toFixed(3)} = <b>${ans} J K<sup>-1</sup></b>.</p>` };
      }, verify: (p) => p.n * 8.314 * Math.log(p.k) },
    { id: 'ct-g10', type: 'nat', level: 3, exams: EX[3], sub: 'calorimetry',
      make(rng) {
        const V = pick(rng, 50, 200, 50); const c = choose(rng, [0.5, 1, 2]);
        const n = V / 1000 * c; const dT = +(n * 57100 / (2 * V * 4.18)).toFixed(2);
        return { q: `${V} mL of ${c} M HCl is mixed with ${V} mL of ${c} M NaOH in an insulated cup. &Delta;H of neutralisation is -57.1 kJ mol<sup>-1</sup>; density 1 g mL<sup>-1</sup>, c = 4.18 J g<sup>-1</sup> K<sup>-1</sup>. Find the rise in temperature in K.`, answer: dT, tol: 0.05, unit: 'K', V, c,
          sol: `<p>Water formed = ${V}/1000 &times; ${c} = ${n} mol. Heat = ${n} &times; 57 100 = ${(n * 57100).toFixed(0)} J.</p><p>Mass of solution = ${2 * V} g. &Delta;T = ${(n * 57100).toFixed(0)} / (${2 * V} &times; 4.18) = <b>${dT} K</b>.</p>` };
      }, verify: (p) => ((p.V / 1000) * p.c * 57100) / (2 * p.V * 4.18) },
    { id: 'ct-g11', type: 'nat', level: 4, exams: EX[4], sub: 'adiabatic process',
      make(rng) {
        const gas = choose(rng, [['monatomic', 5 / 3, [[8, 4], [27, 9], [64, 16]]], ['diatomic', 7 / 5, [[32, 4], [243, 9]]]]);
        const [ratio, f] = choose(rng, gas[2]); const T1 = 144 * int(rng, 2, 4); const exp = rng() < 0.5;
        const T2 = exp ? T1 / f : T1 * f;
        return { q: `An ideal ${gas[0]} gas (&gamma; = ${gas[0] === 'monatomic' ? '5/3' : '7/5'}) at ${T1} K is ${exp ? 'expanded' : 'compressed'} reversibly and adiabatically to ${exp ? ratio + ' times' : '1/' + ratio + ' of'} its volume. Find the final temperature in K.`, answer: T2, tol: 1, unit: 'K', T1, ratio, gam: gas[1], exp,
          sol: `<p>Reversible adiabatic: T V<sup>&gamma;-1</sup> = constant. &gamma; - 1 = ${gas[0] === 'monatomic' ? '2/3' : '2/5'}.</p><p>${ratio}<sup>${gas[0] === 'monatomic' ? '2/3' : '2/5'}</sup> = ${f}. So T<sub>2</sub> = ${T1} ${exp ? '/' : '&times;'} ${f} = <b>${T2} K</b>.</p>` };
      }, verify: (p) => p.T1 * Math.pow(p.exp ? 1 / p.ratio : p.ratio, p.gam - 1) },
    { id: 'ct-g12', type: 'nat', level: 2, exams: EX[2], sub: 'entropy of phase change',
      make(rng) {
        const s = choose(rng, SUBS); const ans = +(s[1] * 1000 / s[2]).toFixed(1);
        return { q: `The enthalpy of vaporisation of ${s[0]} is ${s[1]} kJ mol<sup>-1</sup> at its boiling point of ${s[2]} K. Find the entropy of vaporisation in J K<sup>-1</sup> mol<sup>-1</sup>.`, answer: ans, tol: 0.2, unit: 'J K<sup>-1</sup> mol<sup>-1</sup>', H: s[1], Tb: s[2],
          sol: `<p>At the boiling point &Delta;G = 0, so &Delta;S = &Delta;H/T = ${s[1] * 1000} / ${s[2]} = <b>${ans} J K<sup>-1</sup> mol<sup>-1</sup></b>.</p>` };
      }, verify: (p) => (p.H * 1000) / p.Tb },
    { id: 'ct-g13', type: 'nat', level: 3, exams: EX[3], sub: 'first law at constant pressure',
      make(rng) {
        const n = pick(rng, 1, 5, 1); const dT = pick(rng, 10, 100, 10); const ans = +(-n * R * dT).toFixed(0);
        return { q: `${n} mol of an ideal gas is heated through ${dT} K at constant pressure. Find the work done on the gas in J. (R = 8.314)`, answer: ans, tol: 2, unit: 'J', n, dT,
          sol: `<p>At constant P, w = -P&Delta;V = -nR&Delta;T (using PV = nRT).</p><p>w = -(${n})(8.314)(${dT}) = <b>${ans} J</b>.</p>` };
      }, verify: (p) => -(p.n * 8.314 * p.dT) },
    { id: 'ct-g14', type: 'nat', level: 4, exams: EX[4], sub: 'Born-Haber cycle',
      make(rng) {
        const S = pick(rng, 80, 160, 4); const IE = pick(rng, 400, 520, 4); const D = pick(rng, 120, 250, 2); const E = pick(rng, 300, 350, 2); const L = pick(rng, 700, 800, 5);
        const Hf = +(S + IE + D / 2 - E - L);
        return { q: `For an alkali metal halide MX(s) (kJ mol<sup>-1</sup>): sublimation of M = +${S}, ionisation enthalpy of M = +${IE}, bond dissociation of X<sub>2</sub> = +${D}, electron gain enthalpy of X = -${E}, lattice enthalpy = -${L}. Find &Delta;<sub>f</sub>H of MX.`, answer: Hf, tol: 1, unit: 'kJ mol<sup>-1</sup>', S, IE, D, E, L,
          sol: `<p>&Delta;<sub>f</sub>H = S + IE + &frac12;D + EGE + lattice enthalpy = ${S} + ${IE} + ${D / 2} + (-${E}) + (-${L}) = <b>${Hf} kJ mol<sup>-1</sup></b>.</p>` };
      }, verify: (p) => p.S + p.IE + p.D / 2 + -p.E + -p.L },
    { id: 'ct-g15', type: 'mcq', level: 3, exams: EX[3], sub: 'spontaneity and temperature',
      make(rng) {
        const sH = rng() < 0.5 ? -1 : 1; const sS = rng() < 0.5 ? -1 : 1;
        const right = sH < 0 && sS > 0 ? 'at all temperatures' : sH > 0 && sS < 0 ? 'at no temperature' : sH < 0 ? 'only at low temperatures' : 'only at high temperatures';
        const all = ['at all temperatures', 'at no temperature', 'only at low temperatures', 'only at high temperatures'];
        const { options, answer } = shuffleOpts(rng, right, all.filter((x) => x !== right));
        return { q: `A reaction has &Delta;H ${sH < 0 ? 'negative' : 'positive'} and &Delta;S ${sS < 0 ? 'negative' : 'positive'}. It is spontaneous`, options, answer, sH, sS, right,
          sol: `<p>&Delta;G = &Delta;H - T&Delta;S. Here the &Delta;H term is ${sH < 0 ? 'favourable (negative)' : 'unfavourable (positive)'} and the -T&Delta;S term is ${sS > 0 ? 'favourable (negative)' : 'unfavourable (positive)'}${sH * sS < 0 ? ', so the two work together or against each other at every temperature' : ', so the winner depends on T, because T multiplies only the entropy term'}.</p><p>Spontaneous <b>${right}</b>.</p>` };
      }, verify: (p) => p.answer },
    ...XGN,
  ],
};
export default { ...V5BASE, groups: { ...V5BASE.groups, ...V5GR }, items: [...V5BASE.items, ...V5I], gens: [...V5BASE.gens, ...V5G] };
